lemma LeftExtend(a: seq<int>, key: int, lo: int, mid: int)
  requires Sorted(a)
  requires 0 <= lo <= mid < |a|
  requires a[mid] < key
  requires forall i :: 0 <= i < lo ==> a[i] < key
  ensures forall i :: 0 <= i < mid + 1 ==> a[i] < key
{
  forall i | 0 <= i < mid + 1
    ensures a[i] < key
