method BinarySearch(a: seq<int>, key: int) returns (idx: int)
  requires Sorted(a)
  ensures -1 <= idx < |a|
  ensures idx >= 0 ==> a[idx] == key
  ensures idx == -1 ==> key !in a
{
  var lo := 0;
  var hi := |a|;
  while lo < hi
    invariant 0 <= lo <= hi <= |a|
    invariant forall i :: 0 <= i < lo ==> a[i] < key
    invariant forall i :: hi <= i < |a| ==> a[i] > key
    decreases hi - lo
  {
    var mid := (lo + hi) / 2;
    assert lo <= mid;
    assert mid < hi;

    if a[mid] < key {
      LeftExtend(a, key, lo, mid);
      lo := mid + 1;
    } else if a[mid] > key {
      RightExtend(a, key, hi, mid);
      hi := mid;
    } else {
      assert a[mid] == key;
      return mid;
    }
  }
  assert lo == hi;
  AllDiffer(a, key, lo);
  return -1;
}

