lemma CountExtend(a: seq<int>, x: int, i: nat)
  requires i < |a|
  ensures Count(a[..i + 1], x) == Count(a[..i], x) + (if a[i] == x then 1 else 0)
{
  var s := a[..i + 1];
  assert |s| == i + 1;
  assert |s| > 0;
  calc {
    Count(s, x);
    == Count(s[..(|s| - 1)], x) + (if s[|s| - 1] == x then 1 else 0);
    == {
      assert s[..(|s| - 1)] == a[..i];
      assert s[|s| - 1] == a[i];
    }
      Count(a[..i], x) + (if a[i] == x then 1 else 0);
  }
}

method CountOf(a: seq<int>, x: int) returns (c: nat)
  ensures c == Count(a, x)
{
  c := 0;
  var i: nat := 0;
  while i < |a|
    invariant i <= |a|
    invariant c == Count(a[..i], x)
    decreases |a| - i
  {
    CountExtend(a, x, i);
    if a[i] == x {
      c := c + 1;
    }
    i := i + 1;
  }
}

