  ensures -1 <= idx < |a|
  ensures idx >= 0 ==> a[idx] == key
  ensures idx == -1 ==> key !in a
{
  var lo := 0;
  var hi := |a|;
  while lo < hi
    invariant 0 <= lo <= hi <= |a|
    invariant forall i :: 0 <= i < lo ==> a[i] < key
    invariant forall i :: hi <= i < |a| ==> a[i] > key
    decreases hi - lo
  {
    MidBound(lo, hi);
    var mid := lo + (hi - lo) / 2;
    assert lo <= mid < hi <= |a|;
    assert 0 <= mid < |a|;

    if a[mid] < key {
      forall i: int | 0 <= i < mid + 1
        ensures a[i] < key
      {
        if i < mid {
          SortedLe(a, i, mid);
          assert a[i] <= a[mid];
        } else {
          assert i >= mid;
          assert i < mid + 1;
          assert i == mid;
          assert a[i] <= a[mid];
        }
        assert a[mid] < key;
        assert a[i] <= a[mid] && a[mid] < key;
        assert a[i] < key;
      }
      lo := mid + 1;
    } else if a[mid] > key {
      forall i: int | mid <= i < |a|
        ensures a[i] > key
      {
        if mid < i {
          SortedLe(a, mid, i);
          assert a[mid] <= a[i];
        } else {
          assert i <= mid;
          assert i == mid;
          assert a[mid] <= a[i];
        }
        assert a[mid] > key;
        assert a[mid] <= a[i] && a[mid] > key;
        assert a[i] > key;
      }
      hi := mid;
    } else {
      assert a[mid] == key;
      return mid;
    }
  }
  assert lo == hi;
  forall i: int | 0 <= i < |a|
    ensures a[i] != key
  {
    if i < lo {
      assert 0 <= i < lo;
      assert a[i] < key;
      assert a[i] != key;
    } else {
      assert i >= lo;
      assert lo == hi;
      assert i >= hi;
      assert i < |a|;
      assert hi <= i < |a|;
      assert a[i] > key;
      assert a[i] != key;
    }
  }
  KeyAbsent(a, key);
  return -1;
}
