lemma StrictlySortedAppend(s: seq<int>, v: int)
  requires StrictlySorted(s)
  requires |s| == 0 || s[|s| - 1] < v
  ensures StrictlySorted(s + [v])
{
  var t := s + [v];
  if |s| == 0 {
    assert |t| == 1;
    StrictlySortedShort(t);
  } else {
    assert s[|s| - 1] < v;
    assert |t| == |s| + 1;
    forall p, q | 0 <= p < q < |t|
      ensures t[p] < t[q]
    {
      if q < |s| {
        assert t[p] == s[p];
        assert t[q] == s[q];
        assert 0 <= p < q < |s|;
        StrictlySortedAt(s, p, q);
        assert t[p] < t[q];
      } else {
        assert q == |s|;
        assert t[q] == v;
        assert 0 <= p < |s|;
        assert t[p] == s[p];
        if p == |s| - 1 {
          assert s[p] < v;
          assert t[p] < t[q];
        } else {
          assert p != |s| - 1;
          assert p < |s| - 1;
          assert 0 <= p < |s| - 1 < |s|;
          StrictlySortedAt(s, p, |s| - 1);
          assert s[p] < s[|s| - 1];
          assert s[|s| - 1] < v;
          assert s[p] < v;
          assert t[p] < t[q];
        }
      }
    }
  }
