method Step(a: seq<int>, r0: seq<int>, i0: int) returns (r: seq<int>, i: int)
  requires Sorted(a)
  requires 1 <= i0 < |a|
  requires |r0| >= 1
  requires StrictlySorted(r0)
  requires r0[|r0| - 1] == a[i0 - 1]
  requires forall k {:trigger a[k]} :: 0 <= k < i0 ==> a[k] in r0
  requires forall y {:trigger y in r0} :: y in r0 ==> y in a[..i0]
  ensures i == i0 + 1
  ensures 1 <= i <= |a|
  ensures |r| >= 1
  ensures StrictlySorted(r)
  ensures r[|r| - 1] == a[i - 1]
  ensures forall k {:trigger a[k]} :: 0 <= k < i ==> a[k] in r
  ensures forall y {:trigger y in r} :: y in r ==> y in a[..i]
{
  var add := a[i0] != a[i0 - 1];
  if add {
    SortedLe(a, i0 - 1, i0);
    assert a[i0 - 1] <= a[i0];
    assert a[i0 - 1] != a[i0];
    assert a[i0 - 1] < a[i0];
    assert r0[|r0| - 1] == a[i0 - 1];
    assert r0[|r0| - 1] < a[i0];
    StrictlySortedAppend(r0, a[i0]);

    r := r0 + [a[i0]];
    assert r == r0 + [a[i0]];
    StrictlySortedSame(r0 + [a[i0]], r);
    assert StrictlySorted(r);
    assert |r0| >= 1;
    assert |r| == |r0| + 1;
    assert |r| >= 1;
    assert (r0 + [a[i0]])[|r0|] == a[i0];
    assert r[|r0|] == a[i0];
    assert |r| - 1 == |r0|;
    assert r[|r| - 1] == a[i0];
    assert 0 <= |r| - 1 < |r|;
    AtIndexIn(r, |r| - 1);
    assert r[|r| - 1] in r;
    assert a[i0] in r;

    forall k {:trigger a[k]} | 0 <= k < i0
      ensures a[k] in r
    {
      assert a[k] in r0;
      InOldStillInAppend(r0, a[i0], a[k]);
      assert a[k] in r0 + [a[i0]];
      SameMembers(r0 + [a[i0]], r, a[k]);
      assert a[k] in r;
    }

    forall k {:trigger a[k]} | 0 <= k < i0 + 1
      ensures a[k] in r
    {
      if k < i0 {
        assert a[k] in r;
      } else {
        assert k == i0;
        assert a[i0] in r;
      }
    }

    forall y {:trigger y in r} | y in r
      ensures y in a[..i0 + 1]
    {
