{
  var left := prefix + [key];
  MultisetAppend(prefix, [key]);
  MultisetAppend(left, tail);
  MultisetAppend(sorted, tail);
  assert multiset([key]) == multiset{key};
  assert multiset(left) == multiset(prefix) + multiset([key]);
  assert multiset(left) == multiset(prefix) + multiset{key};
  assert multiset(sorted) == multiset(left);
  assert left + tail == prefix + [key] + tail;
  calc {
    multiset(whole);
    == multiset(sorted + tail);
    == multiset(sorted) + multiset(tail);
    == multiset(left) + multiset(tail);
    == multiset(left + tail);
