lemma UpdateConcat(s: seq<int>, i: int, v: int)
  requires 0 <= i < |s|
  ensures s[i := v] == s[.. i] + [v] + s[i + 1 ..]
{
  var u := s[i := v];
  var head0 := s[.. i];
  var mid := [v];
  var tail := s[i + 1 ..];
  var r := head0 + mid + tail;
  UpdateFrame(s, i, v);
  assert |head0| == i;
  assert |tail| == |s| - i - 1;
  assert |r| == |s|;

  forall j | 0 <= j < |s|
    ensures u[j] == r[j]
  {
    if j < i {
      assert u[j] == s[j];
      var rest := mid + tail;
      assert head0 + mid + tail == head0 + (mid + tail);
      assert r == head0 + rest;
      ConcatTake(head0, rest);
      assert r[.. |head0|] == head0;
      assert r[j] == r[.. |head0|][j];
      assert head0[j] == s[j];
    } else if j == i {
      assert u[j] == v;
      var headmid := head0 + mid;
      assert head0 + mid + tail == headmid + tail;
      assert r == headmid + tail;
      assert |headmid| == i + 1;
      ConcatTake(headmid, tail);
      assert r[.. |headmid|] == headmid;
      assert r[i] == headmid[i];
      ConcatDrop(head0, mid);
      assert headmid[|head0| ..] == mid;
      assert headmid[i] == headmid[|head0| ..][0];
      assert mid[0] == v;
    } else {
      assert j > i;
      assert u[j] == s[j];
      var headmid := head0 + mid;
      assert head0 + mid + tail == headmid + tail;
      assert r == headmid + tail;
      assert |headmid| == i + 1;
      ConcatDrop(headmid, tail);
      assert r[|headmid| ..] == tail;
      assert r[j] == r[|headmid| ..][j - |headmid|];
      assert tail[j - i - 1] == s[(i + 1) + (j - i - 1)];
      assert (i + 1) + (j - i - 1) == j;
    }
  }
  assert u == r;
}

