  assert A + [b] + C + [d] + E == (((A + [b]) + C) + [d]) + E;
  assert r == Cat5(A, b, C, d, E);
  assert |AB| == |A| + 1;
  assert |ABC| == |A| + 1 + |C|;
  assert |ABCD| == |A| + |C| + 2;
  assert |r| == |A| + |C| + |E| + 2;

  if k < |A| {
    ConcatIndexLeft(A, Bb, k);
    assert AB[k] == A[k];
    ConcatIndexLeft(AB, C, k);
    assert ABC[k] == AB[k];
    ConcatIndexLeft(ABC, Dd, k);
    assert ABCD[k] == ABC[k];
    ConcatIndexLeft(ABCD, E, k);
    assert r[k] == ABCD[k];
    val := A[k];
    assert r[k] == val;
  } else if k == |A| {
    ConcatIndexRight(A, Bb, 0);
    assert AB[|A|] == Bb[0];
    assert Bb[0] == b;
    assert AB[k] == b;
    ConcatIndexLeft(AB, C, k);
    assert ABC[k] == AB[k];
    ConcatIndexLeft(ABC, Dd, k);
    assert ABCD[k] == ABC[k];
    ConcatIndexLeft(ABCD, E, k);
    assert r[k] == ABCD[k];
    val := b;
    assert r[k] == val;
  } else if k < |A| + |C| + 1 {
    var kk := k - |A| - 1;
    assert 0 <= kk < |C|;
    ConcatIndexRight(AB, C, kk);
    assert |AB| + kk == k;
    assert ABC[k] == C[kk];
    ConcatIndexLeft(ABC, Dd, k);
    assert ABCD[k] == ABC[k];
    ConcatIndexLeft(ABCD, E, k);
    assert r[k] == ABCD[k];
    val := C[kk];
    assert r[k] == val;
  } else if k == |A| + |C| + 1 {
    assert k == |ABC|;
    ConcatIndexRight(ABC, Dd, 0);
    assert ABCD[k] == Dd[0];
    assert Dd[0] == d;
    ConcatIndexLeft(ABCD, E, k);
    assert r[k] == ABCD[k];
    val := d;
    assert r[k] == val;
  } else {
    var kk := k - |A| - |C| - 2;
    assert 0 <= kk < |E|;
    assert |ABCD| + kk == k;
    ConcatIndexRight(ABCD, E, kk);
    assert r[k] == E[kk];
    val := E[kk];
    assert r[k] == val;
  }
  assert Cat5(A, b, C, d, E)[k] == r[k];
  assert Cat5(A, b, C, d, E)[k] == val;
}

lemma {:vcs_split_on_every_assert} SplitTwo(s: seq<int>, p: int, q: int)
  requires 0 <= p < q < |s|
  ensures s == Cat5(s[..p], s[p], s[p + 1..q], s[q], s[q + 1..])
{
  var A := s[..p];
  var b := s[p];
  var C := s[p + 1..q];
  var d := s[q];
  var E := s[q + 1..];
  var r := Cat5(A, b, C, d, E);
  assert |A| == p;
  assert |C| == q - (p + 1);
  assert |E| == |s| - (q + 1);
  assert |A| + |C| + |E| + 2 == |s|;
  assert |A| + |C| + 1 == q;
  forall k | 0 <= k < |s|
    ensures s[k] == r[k]
  {
    var val := FiveIndex(A, b, C, d, E, k);
    assert r[k] == val;
    if k < |A| {
      assert val == A[k];
      SliceIndex(s, 0, p, k);
      assert A[k] == s[k];
      assert s[k] == val;
    } else if k == |A| {
      assert val == b;
      assert s[k] == b;
    } else if k < |A| + |C| + 1 {
      assert |A| < k < |A| + |C| + 1;
      var kk := k - |A| - 1;
      assert val == C[kk];
      SliceIndex(s, p + 1, q, kk);
      assert C[kk] == s[p + 1 + kk];
      assert p + 1 + kk == k;
      assert s[k] == val;
    } else if k == |A| + |C| + 1 {
      assert val == d;
      assert k == q;
      assert s[k] == d;
    } else {
      assert k > |A| + |C| + 1;
      var kk := k - |A| - |C| - 2;
      assert val == E[kk];
      assert kk == k - (q + 1);
      SliceIndex(s, q + 1, |s|, kk);
      assert E[kk] == s[q + 1 + kk];
      assert q + 1 + kk == k;
      assert s[k] == val;
    }
  }
  assert |r| == |s|;
  SeqEq(s, r);
}

lemma {:vcs_split_on_every_assert} SwapRearrange(s: seq<int>, p: int, q: int)
  requires 0 <= p < q < |s|
  ensures Swapped(s, p, q) == Cat5(s[..p], s[q], s[p + 1..q], s[p], s[q + 1..])
{
  var t := Swapped(s, p, q);
  SwappedProps(s, p, q);
  var A := s[..p];
  var b := s[q];
  var C := s[p + 1..q];
  var d := s[p];
  var E := s[q + 1..];
  var r := Cat5(A, b, C, d, E);
  assert |A| == p;
  assert |C| == q - (p + 1);
  assert |E| == |s| - (q + 1);
  assert |A| + |C| + |E| + 2 == |s|;
  assert |A| + |C| + 1 == q;
  assert |t| == |s|;
  forall k | 0 <= k < |s|
    ensures t[k] == r[k]
  {
    var val := FiveIndex(A, b, C, d, E, k);
    assert r[k] == val;
    if k < |A| {
      assert t[k] == s[k];
      assert val == A[k];
      SliceIndex(s, 0, p, k);
      assert A[k] == s[k];
      assert t[k] == val;
    } else if k == |A| {
      assert k == p;
      assert t[k] == s[q];
      assert val == b;
      assert b == s[q];
      assert t[k] == val;
    } else if k < |A| + |C| + 1 {
      assert |A| < k < |A| + |C| + 1;
      assert k != p && k != q;
      assert t[k] == s[k];
      var kk := k - |A| - 1;
      assert val == C[kk];
      SliceIndex(s, p + 1, q, kk);
      assert C[kk] == s[p + 1 + kk];
      assert p + 1 + kk == k;
      assert t[k] == val;
    } else if k == |A| + |C| + 1 {
      assert k == q;
      assert t[k] == s[p];
      assert val == d;
      assert d == s[p];
      assert t[k] == val;
    } else {
      assert k > q;
      assert k != p && k != q;
      assert t[k] == s[k];
      var kk := k - |A| - |C| - 2;
      assert val == E[kk];
      assert kk == k - (q + 1);
      SliceIndex(s, q + 1, |s|, kk);
      assert E[kk] == s[q + 1 + kk];
      assert q + 1 + kk == k;
      assert t[k] == val;
    }
  }
  assert |r| == |s|;
  SeqEq(t, r);
}

lemma {:vcs_split_on_every_assert} SwapMultiset(s: seq<int>, p: int, q: int)
  requires 0 <= p < q < |s|
  ensures multiset(Swapped(s, p, q)) == multiset(s)
{
  var A := s[..p];
  var C := s[p + 1..q];
  var E := s[q + 1..];
  var ap := s[p];
  var aq := s[q];
  SplitTwo(s, p, q);
  assert s == Cat5(A, ap, C, aq, E);
  SwapRearrange(s, p, q);
  var t := Swapped(s, p, q);
  assert t == Cat5(A, aq, C, ap, E);
  assert Cat5(A, ap, C, aq, E) == A + [ap] + C + [aq] + E;
  assert Cat5(A, aq, C, ap, E) == A + [aq] + C + [ap] + E;
  MultisetFive(A, [ap], C, [aq], E);
  MultisetFive(A, [aq], C, [ap], E);
  var ms := multiset(A) + multiset([ap]) + multiset(C) + multiset([aq]) + multiset(E);
  var mt := multiset(A) + multiset([aq]) + multiset(C) + multiset([ap]) + multiset(E);
  assert multiset(s) == ms;
  assert multiset(t) == mt;
  forall v | true
    ensures ms[v] == mt[v]
  {
    SingletonCount(ap, v);
    SingletonCount(aq, v);
    var left := multiset(A)[v];
    var mid := multiset(C)[v];
    var right := multiset(E)[v];
    var cp := multiset([ap])[v];
    var cq := multiset([aq])[v];
    MultisetSumIndex(multiset(A), multiset([ap]), multiset(C), multiset([aq]), multiset(E), v);
    MultisetSumIndex(multiset(A), multiset([aq]), multiset(C), multiset([ap]), multiset(E), v);
    assert ms[v] == left + cp + mid + cq + right;
    assert mt[v] == left + cq + mid + cp + right;
    assert left + cp + mid + cq + right == left + cq + mid + cp + right;
  }
  MultisetExt(ms, mt);
  assert multiset(s) == multiset(t);
}

