    PrefixSlice(s, j, right);
    assert s[..right] == L + R;
    var C := L + R;
    assert |L| == j && |R| == right - j;
    assert |L| > 0 && |R| > 0;
    assert L[|L| - 1] == s[j - 1];
    assert R[0] == s[j];
    assert L[|L| - 1] <= R[0];
    forall x, y | 0 <= x < y < |C|
      ensures C[x] <= C[y]
    {
      if y < |L| {
        ConcatIndexLeft(L, R, x);
        ConcatIndexLeft(L, R, y);
        assert C[x] == L[x];
        assert C[y] == L[y];
        SortedAt(L, x, y);
        assert C[x] <= C[y];
      } else if x >= |L| {
        var kx := x - |L|;
        var ky := y - |L|;
        assert 0 <= kx < ky < |R|;
        ConcatIndexRight(L, R, kx);
        ConcatIndexRight(L, R, ky);
        assert C[x] == R[kx];
        assert C[y] == R[ky];
        SortedAt(R, kx, ky);
        assert C[x] <= C[y];
      } else {
        var ky := y - |L|;
        assert 0 <= ky < |R|;
        ConcatIndexLeft(L, R, x);
        ConcatIndexRight(L, R, ky);
        assert C[x] == L[x];
        assert C[y] == R[ky];
        if x < |L| - 1 {
          SortedAt(L, x, |L| - 1);
        } else {
          assert x == |L| - 1;
        }
        assert L[x] <= L[|L| - 1];
        if ky == 0 {
          assert R[ky] == R[0];
        } else {
          SortedAt(R, 0, ky);
        }
        assert R[0] <= R[ky];
        assert L[|L| - 1] <= R[0];
        assert L[x] <= L[|L| - 1];
        assert L[x] <= R[0];
        assert L[x] <= R[ky];
        assert C[x] <= C[y];
      }
    }
    SortedFromForall(C);
    assert s[..right] == C;
    assert Sorted(s[..right]);
  }
}

lemma {:vcs_split_on_every_assert} SwapPreserves(s: seq<int>, j: int, i: int) returns (t: seq<int>)
  requires 1 <= j <= i < |s|
  requires Sorted(s[..j])
  requires Sorted(s[j..i + 1])
  requires s[j - 1] > s[j]
  requires forall k {:trigger s[k]} :: j < k <= i ==> s[j - 1] <= s[k]
  ensures t == Swapped(s, j - 1, j)
  ensures |t| == |s|
  ensures Sorted(t[..j - 1])
  ensures Sorted(t[j - 1..i + 1])
  ensures multiset(t) == multiset(s)
  ensures forall k :: j - 1 < k <= i && j > 1 ==> t[j - 2] <= t[k]
{
  var p := j - 1;
  t := Swapped(s, p, j);
  SwappedProps(s, p, j);
  SwapMultiset(s, p, j);
  assert t == Swapped(s, p, j);
  assert |t| == |s|;
  assert multiset(t) == multiset(s);

  var sp := s[..p];
  var tp := t[..p];
  forall k | 0 <= k < p
    ensures tp[k] == sp[k]
  {
    assert k != p && k != j;
    assert t[k] == s[k];
    SliceIndex(t, 0, p, k);
    SliceIndex(s, 0, p, k);
    assert tp[k] == t[k];
    assert sp[k] == s[k];
  }
  assert |tp| == p == |sp|;
  SeqEq(tp, sp);

  forall x, y | 0 <= x < y < p
    ensures sp[x] <= sp[y]
  {
    SortedAt(s[..j], x, y);
    SliceIndex(s, 0, j, x);
    SliceIndex(s, 0, j, y);
    SliceIndex(s, 0, p, x);
    SliceIndex(s, 0, p, y);
    assert (s[..j])[x] == s[x];
    assert (s[..j])[y] == s[y];
    assert sp[x] == s[x];
    assert sp[y] == s[y];
  }
  SortedFromForall(sp);
  assert Sorted(tp);
  assert Sorted(t[..j - 1]);

  forall u, v | p <= u < v <= i
    ensures t[u] <= t[v]
  {
    if u == p && v == j {
      assert t[u] == s[j];
      assert t[v] == s[p];
      assert s[p] > s[j];
      assert s[j] <= s[p];
      assert t[u] <= t[v];
    } else if u == p {
      assert v > j;
      assert t[u] == s[j];
      assert v != p && v != j;
      assert t[v] == s[v];
      SuffixAt(s, j, i, j, v);
      assert s[j] <= s[v];
      assert t[u] <= t[v];
    } else if u == j {
      assert v > j;
      assert t[u] == s[p];
      assert v != p && v != j;
      assert t[v] == s[v];
      assert s[p] <= s[v];
      assert t[u] <= t[v];
    } else {
      assert u > j && v > u;
      assert u != p && u != j && v != p && v != j;
      assert t[u] == s[u];
      assert t[v] == s[v];
      SuffixAt(s, j, i, u, v);
      assert t[u] <= t[v];
    }
  }

  var suf := t[p..i + 1];
  assert |suf| == i + 1 - p;
  forall x, y | 0 <= x < y < |suf|
    ensures suf[x] <= suf[y]
  {
    var u := p + x;
    var v := p + y;
    assert p <= u < v <= i;
    assert t[u] <= t[v];
    SliceIndex(t, p, i + 1, x);
    SliceIndex(t, p, i + 1, y);
    assert suf[x] == t[u];
    assert suf[y] == t[v];
  }
  SortedFromForall(suf);
  assert suf == t[j - 1..i + 1];
  assert Sorted(t[j - 1..i + 1]);

  forall k | j - 1 < k <= i && j > 1
    ensures t[j - 2] <= t[k]
  {
    assert 0 <= j - 2 < |t|;
    assert j - 2 != p && j - 2 != j;
    assert t[j - 2] == s[j - 2];
    SortedAt(s[..j], j - 2, j - 1);
    SliceIndex(s, 0, j, j - 2);
    SliceIndex(s, 0, j, j - 1);
    assert (s[..j])[j - 2] == s[j - 2];
    assert (s[..j])[j - 1] == s[j - 1];
    assert s[j - 2] <= s[j - 1];
    if k == j {
      assert t[k] == s[j - 1];
      assert t[j - 2] <= t[k];
    } else {
      assert k > j;
      assert k != p && k != j;
      assert t[k] == s[k];
      assert s[j - 1] <= s[k];
      assert s[j - 2] <= s[k];
      assert t[j - 2] <= t[k];
    }
  }
}

lemma {:vcs_split_on_every_assert} ArrayMatchesSwap(a: array<int>, pre: seq<int>, p: int, q: int)
  requires 0 <= p < q < a.Length
  requires |pre| == a.Length
  requires a[p] == pre[q]
  requires a[q] == pre[p]
  requires forall k :: 0 <= k < a.Length && k != p && k != q ==> a[k] == pre[k]
  ensures a[..] == Swapped(pre, p, q)
{
  var t := Swapped(pre, p, q);
  SwappedProps(pre, p, q);
  forall k | 0 <= k < a.Length
    ensures a[..][k] == t[k]
  {
    if k == p {
      assert a[k] == pre[q];
      assert t[k] == pre[q];
    } else if k == q {
      assert a[k] == pre[p];
      assert t[k] == pre[p];
    } else {
      assert a[k] == pre[k];
      assert t[k] == pre[k];
    }
    assert a[..][k] == a[k];
  }
  assert |a[..]| == a.Length == |t|;
  SeqEq(a[..], t);
}

method {:vcs_split_on_every_assert} SwapAdjacent(a: array<int>, j: int)
  requires 1 <= j < a.Length
  modifies a
  ensures a[..] == Swapped(old(a[..]), j - 1, j)
{
  ghost var pre := old(a[..]);
  assert pre == a[..];
  var p := j - 1;
  assert 0 <= p < j < a.Length;
  var tmp := a[j];
  assert tmp == pre[j];
  assert a[p] == pre[p];

  a[j] := a[p];
  assert a[j] == pre[p];
  assert forall k :: 0 <= k < a.Length && k != j ==> a[k] == pre[k];

  ghost var mid := a[..];
  forall k | 0 <= k < a.Length && k != j
    ensures mid[k] == pre[k]
  {
    assert a[k] == pre[k];
    assert mid[k] == a[k];
  }
  assert mid[j] == a[j];
  assert mid[j] == pre[p];

  a[p] := tmp;
  assert a[p] == tmp;
  assert tmp == pre[j];
  assert a[p] == pre[j];
  assert forall k :: 0 <= k < a.Length && k != p ==> a[k] == mid[k];
  assert p != j;
  assert a[j] == mid[j];
  assert a[j] == pre[p];

  forall k | 0 <= k < a.Length && k != p && k != j
    ensures a[k] == pre[k]
  {
    assert a[k] == mid[k];
    assert mid[k] == pre[k];
  }
  ArrayMatchesSwap(a, pre, p, j);
  assert pre == old(a[..]);
  assert a[..] == Swapped(old(a[..]), j - 1, j);
}

method {:vcs_split_on_every_assert} InsertionSort(a: array<int>)
  modifies a
  ensures Sorted(a[..])
  ensures multiset(a[..]) == multiset(old(a[..]))
{
