      assert a[..] == t;
      assert multiset(t) == multiset(pre);
      assert multiset(a[..]) == multiset(t);
      assert multiset(a[..]) == multiset(old(a[..]));

      j := j - 1;
      assert j == j0 - 1;
      assert 0 <= j <= i;

      assert Sorted(t[..j0 - 1]);
      assert t[..j] == t[..j0 - 1];
      assert a[..j] == t[..j];
      assert Sorted(a[..j]);

      assert Sorted(t[j0 - 1..i + 1]);
      assert t[j..i + 1] == t[j0 - 1..i + 1];
      assert a[j..i + 1] == t[j..i + 1];
      assert Sorted(a[j..i + 1]);

      forall k | j < k <= i
        ensures j > 0 ==> a[j - 1] <= a[k]
      {
        if j > 0 {
          assert j0 > 1;
          assert j0 - 1 < k <= i;
          assert t[j0 - 2] <= t[k];
          assert 0 <= j - 1 < a.Length;
          assert a[j - 1] == t[j - 1];
          assert j - 1 == j0 - 2;
          assert a[k] == t[k];
          assert a[j - 1] <= a[k];
        }
      }
    }

    if j > 0 {
      assert a[j - 1] <= a[j];
