lemma MultisetCons(x: int, s: seq<int>)
  ensures multiset([x] + s) == multiset{x} + multiset(s)
{
  var xs := [x] + s;
  ConsTail(x, s);
  assert xs[0] == x;
  assert xs[1..] == s;
  assert xs == [xs[0]] + xs[1..];
  assert multiset(xs) == multiset{xs[0]} + multiset(xs[1..]);
  assert multiset(xs) == multiset{x} + multiset(s);
