lemma MultisetAppend(xs: seq<int>, ys: seq<int>)
  ensures multiset(xs + ys) == multiset(xs) + multiset(ys)
  decreases |xs|
{
  if xs == [] {
    assert xs + ys == ys;
  } else {
    MultisetAppend(xs[1..], ys);
    assert xs + ys == [xs[0]] + (xs[1..] + ys);
    assert xs == [xs[0]] + xs[1..];
    MultisetCons(xs[0], xs[1..]);
    assert multiset([xs[0]] + xs[1..]) == multiset{xs[0]} + multiset(xs[1..]);
    assert multiset(xs) == multiset{xs[0]} + multiset(xs[1..]);
    MultisetCons(xs[0], xs[1..] + ys);
    assert multiset(xs[1..] + ys) == multiset(xs[1..]) + multiset(ys);
    calc {
      multiset(xs + ys);
      == multiset([xs[0]] + (xs[1..] + ys));
      == multiset{xs[0]} + multiset(xs[1..] + ys);
      == multiset{xs[0]} + (multiset(xs[1..]) + multiset(ys));
      == (multiset{xs[0]} + multiset(xs[1..])) + multiset(ys);
      == multiset(xs) + multiset(ys);
    }
  }
}

