lemma InsertBounded(s: seq<int>, key: int, bound: int)
  requires bound <= key
  requires forall n :: 0 <= n < |s| ==> bound <= s[n]
  ensures forall n :: 0 <= n < |Insert(s, key)| ==> bound <= Insert(s, key)[n]
  decreases |s|
{
  if |s| == 0 || key <= s[0] {
    var r := Insert(s, key);
    assert r == [key] + s;
    forall n | 0 <= n < |r|
      ensures bound <= r[n]
    {
      if n == 0 {
        assert r[0] == key;
        assert bound <= key;
      } else {
        assert r[n] == s[n - 1];
        assert bound <= s[n - 1];
      }
    }
  } else {
    forall n | 0 <= n < |s[1..]|
      ensures bound <= s[1..][n]
    {
      assert s[1..][n] == s[n + 1];
      assert 0 <= n + 1 < |s|;
      assert bound <= s[n + 1];
    }
    InsertBounded(s[1..], key, bound);
    var rest := Insert(s[1..], key);
    var r := Insert(s, key);
    assert r == [s[0]] + rest;
    forall n | 0 <= n < |r|
      ensures bound <= r[n]
    {
      if n == 0 {
        assert r[0] == s[0];
        assert bound <= s[0];
      } else {
        assert r[n] == rest[n - 1];
        assert bound <= rest[n - 1];
      }
    }
  }
}

