lemma {:vcs_split_on_every_assert} FiveIndex(A: seq<int>, b: int, C: seq<int>, d: int, E: seq<int>, k: int) returns (val: int)
  requires 0 <= k < |A| + |C| + |E| + 2
  ensures Cat5(A, b, C, d, E)[k] == val
  ensures k < |A| ==> val == A[k]
  ensures k == |A| ==> val == b
  ensures |A| < k < |A| + |C| + 1 ==> val == C[k - |A| - 1]
