  assert a[..] == withAp;
  assert withAp == withPre;
  assert a[..] == withPre;
  assert Swapped(pre, p, j) == pre[p := pre[j]][j := pre[p]];
  assert pre[p := pre[j]][j := pre[p]] == withPre;
  assert a[..] == Swapped(pre, p, j);
  assert p == j - 1;
  assert pre == old(a[..]);
  assert a[..] == Swapped(old(a[..]), j - 1, j);
}

