lemma {:vcs_split_on_every_assert} PrefixSlice(s: seq<int>, j: int, right: int)
  requires 0 <= j <= right <= |s|
  ensures s[..right] == s[..j] + s[j..right]
{
  var L := s[..j];
  var R := s[j..right];
  var C := L + R;
  var P := s[..right];
  assert s[..right] == s[0..right];
  assert s[..j] == s[0..j];
  forall k | 0 <= k < right
    ensures P[k] == C[k]
  {
    SliceIndex(s, 0, right, k);
    assert P[k] == s[k];
    if k < j {
      ConcatIndexLeft(L, R, k);
      assert C[k] == L[k];
      SliceIndex(s, 0, j, k);
      assert L[k] == s[k];
      assert P[k] == C[k];
    } else {
      var kk := k - j;
      assert 0 <= kk < |R|;
      ConcatIndexRight(L, R, kk);
      assert |L| == j;
      assert C[k] == R[kk];
      SliceIndex(s, j, right, kk);
      assert R[kk] == s[j + kk];
      assert j + kk == k;
      assert P[k] == C[k];
    }
  }
  assert |P| == right;
  assert |C| == right;
  SeqEq(P, C);
}

lemma {:vcs_split_on_every_assert} JoinSorted(s: seq<int>, j: int, right: int)
  requires 0 <= j <= right <= |s|
  requires Sorted(s[..j])
  requires Sorted(s[j..right])
  requires j == 0 || j == right || s[j - 1] <= s[j]
  ensures Sorted(s[..right])
{
  if j == 0 {
    assert s[..right] == s[0..right];
    assert s[j..right] == s[0..right];
    assert s[..right] == s[j..right];
    SortedEq(s[j..right], s[..right]);
  } else if j == right {
    assert s[..right] == s[..j];
    SortedEq(s[..j], s[..right]);
  } else {
    assert 0 < j < right;
    assert s[j - 1] <= s[j];
    var L := s[..j];
    var R := s[j..right];
    PrefixSlice(s, j, right);
    assert s[..right] == L + R;
    var C := L + R;
    assert |L| == j && |R| == right - j;
    assert |L| > 0 && |R| > 0;
    assert s[..j] == s[0..j];
    SliceIndex(s, 0, j, j - 1);
    assert L[j - 1] == s[j - 1];
    assert L[|L| - 1] == s[j - 1];
    SliceIndex(s, j, right, 0);
    assert R[0] == s[j];
    assert L[|L| - 1] <= R[0];
    forall x, y | 0 <= x < y < |C|
      ensures C[x] <= C[y]
    {
      if y < |L| {
        ConcatIndexLeft(L, R, x);
        ConcatIndexLeft(L, R, y);
        assert C[x] == L[x];
        assert C[y] == L[y];
        SortedAt(L, x, y);
        assert C[x] <= C[y];
      } else if x >= |L| {
        var kx := x - |L|;
        var ky := y - |L|;
        assert 0 <= kx < ky < |R|;
        ConcatIndexRight(L, R, kx);
        ConcatIndexRight(L, R, ky);
        assert C[x] == R[kx];
        assert C[y] == R[ky];
        SortedAt(R, kx, ky);
        assert C[x] <= C[y];
      } else {
        var ky := y - |L|;
        assert 0 <= ky < |R|;
        ConcatIndexLeft(L, R, x);
        ConcatIndexRight(L, R, ky);
        assert C[x] == L[x];
        assert C[y] == R[ky];
        if x < |L| - 1 {
          SortedAt(L, x, |L| - 1);
        } else {
          assert x == |L| - 1;
        }
        assert L[x] <= L[|L| - 1];
        if ky == 0 {
          assert R[ky] == R[0];
        } else {
          SortedAt(R, 0, ky);
        }
        assert R[0] <= R[ky];
        assert L[|L| - 1] <= R[0];
        assert L[x] <= R[0];
        assert L[x] <= R[ky];
        assert C[x] <= C[y];
      }
    }
    SortedFromForall(C);
    assert s[..right] == C;
    assert Sorted(s[..right]);
  }
}

lemma {:vcs_split_on_every_assert} SwapPreserves(s: seq<int>, j: int, i: int) returns (t: seq<int>)
  requires 1 <= j <= i < |s|
  requires Sorted(s[..j])
  requires Sorted(s[j..i + 1])
  requires s[j - 1] > s[j]
  requires forall k {:trigger s[k]} :: j < k <= i ==> s[j - 1] <= s[k]
  ensures t == Swapped(s, j - 1, j)
  ensures |t| == |s|
  ensures Sorted(t[..j - 1])
  ensures Sorted(t[j - 1..i + 1])
  ensures multiset(t) == multiset(s)
  ensures forall k {:trigger t[k]} :: j - 1 < k <= i && j > 1 ==> t[j - 2] <= t[k]
{
  var p := j - 1;
  assert j == p + 1;
  t := Swapped(s, p, j);
  SwappedProps(s, p, j);
  SwapMultiset(s, p, j);
  assert t == Swapped(s, p, j);
  assert |t| == |s|;
  assert multiset(t) == multiset(s);

  var sp := s[..p];
  var tp := t[..p];
  forall k | 0 <= k < p
    ensures tp[k] == sp[k]
  {
    assert k != p && k != j;
    assert t[k] == s[k];
    SliceIndex(t, 0, p, k);
    SliceIndex(s, 0, p, k);
    assert tp[k] == t[k];
    assert sp[k] == s[k];
  }
  assert |tp| == p == |sp|;
  SeqEq(tp, sp);

  forall x, y | 0 <= x < y < p
    ensures sp[x] <= sp[y]
  {
    SortedAt(s[..j], x, y);
    SliceIndex(s, 0, j, x);
    SliceIndex(s, 0, j, y);
    SliceIndex(s, 0, p, x);
    SliceIndex(s, 0, p, y);
    assert (s[..j])[x] == s[x];
    assert (s[..j])[y] == s[y];
    assert sp[x] == s[x];
    assert sp[y] == s[y];
  }
  SortedFromForall(sp);
  assert Sorted(tp);
  assert tp == t[..p];
  assert t[..p] == t[..j - 1];
  assert Sorted(t[..j - 1]);

  forall u, v | p <= u < v <= i
    ensures t[u] <= t[v]
  {
    if u == p && v == j {
      assert t[u] == s[j];
      assert t[v] == s[p];
      assert s[p] > s[j];
      assert s[j] <= s[p];
      assert t[u] <= t[v];
    } else if u == p {
      assert j == p + 1;
      assert v != j;
      assert v > p;
      assert v > j;
      assert t[u] == s[j];
