  forall k | 0 <= k < hi - lo
    ensures A[k] == B[k]
  {
    assert A[k] == a[lo + k];
    assert s[lo + k] == a[lo + k];
    SliceIndex(s, lo, hi, k);
    assert B[k] == s[lo + k];
  }
  assert |A| == hi - lo;
  assert |B| == hi - lo;
  SeqEq(A, B);
}

