  requires lo <= x < y <= hi
  ensures s[x] <= s[y]
{
  SortedAt(s[lo..hi + 1], x - lo, y - lo);
  SliceIndex(s, lo, hi + 1, x - lo);
  SliceIndex(s, lo, hi + 1, y - lo);
  assert (s[lo..hi + 1])[x - lo] == s[x];
