lemma {:vcs_split_on_every_assert} PrefixSlice(s: seq<int>, j: int, right: int)
  requires 0 <= j <= right <= |s|
  ensures s[..right] == s[..j] + s[j..right]
{
  var L := s[..j];
  var R := s[j..right];
  var C := L + R;
  var P := s[..right];
  assert s[..right] == s[0..right];
  assert s[..j] == s[0..j];
  forall k | 0 <= k < right
    ensures P[k] == C[k]
  {
    SliceIndex(s, 0, right, k);
    assert P[k] == s[k];
    if k < j {
      ConcatIndexLeft(L, R, k);
      assert C[k] == L[k];
      SliceIndex(s, 0, j, k);
      assert L[k] == s[k];
      assert P[k] == C[k];
    } else {
      var kk := k - j;
      assert 0 <= kk < |R|;
      ConcatIndexRight(L, R, kk);
      assert |L| == j;
      assert C[k] == R[kk];
      SliceIndex(s, j, right, kk);
      assert R[kk] == s[j + kk];
      assert j + kk == k;
      assert P[k] == C[k];
    }
  }
  assert |P| == right;
  assert |C| == right;
  SeqEq(P, C);
}

lemma {:vcs_split_on_every_assert} JoinSorted(s: seq<int>, j: int, right: int)
  requires 0 <= j <= right <= |s|
  requires Sorted(s[..j])
  requires Sorted(s[j..right])
  requires j == 0 || j == right || s[j - 1] <= s[j]
  ensures Sorted(s[..right])
{
  if j == 0 {
    assert s[..right] == s[0..right];
    assert s[j..right] == s[0..right];
    assert s[..right] == s[j..right];
    SortedEq(s[j..right], s[..right]);
  } else if j == right {
    assert s[..right] == s[..j];
    SortedEq(s[..j], s[..right]);
  } else {
    assert 0 < j < right;
    assert s[j - 1] <= s[j];
    var L := s[..j];
    var R := s[j..right];
    PrefixSlice(s, j, right);
    assert s[..right] == L + R;
    var C := L + R;
    assert |L| == j && |R| == right - j;
    assert |L| > 0 && |R| > 0;
    assert s[..j] == s[0..j];
    SliceIndex(s, 0, j, j - 1);
    assert L[j - 1] == s[j - 1];
    assert L[|L| - 1] == s[j - 1];
    SliceIndex(s, j, right, 0);
    assert R[0] == s[j];
    assert L[|L| - 1] <= R[0];
    forall x, y | 0 <= x < y < |C|
      ensures C[x] <= C[y]
    {
      if y < |L| {
        ConcatIndexLeft(L, R, x);
        ConcatIndexLeft(L, R, y);
        assert C[x] == L[x];
        assert C[y] == L[y];
        SortedAt(L, x, y);
        assert C[x] <= C[y];
      } else if x >= |L| {
        var kx := x - |L|;
        var ky := y - |L|;
        assert 0 <= kx < ky < |R|;
        ConcatIndexRight(L, R, kx);
        ConcatIndexRight(L, R, ky);
        assert C[x] == R[kx];
        assert C[y] == R[ky];
        SortedAt(R, kx, ky);
        assert C[x] <= C[y];
      } else {
        var ky := y - |L|;
        assert 0 <= ky < |R|;
        ConcatIndexLeft(L, R, x);
        ConcatIndexRight(L, R, ky);
        assert C[x] == L[x];
        assert C[y] == R[ky];
        if x < |L| - 1 {
          SortedAt(L, x, |L| - 1);
        } else {
          assert x == |L| - 1;
        }
        assert L[x] <= L[|L| - 1];
        if ky == 0 {
          assert R[ky] == R[0];
        } else {
          SortedAt(R, 0, ky);
        }
        assert R[0] <= R[ky];
        assert L[|L| - 1] <= R[0];
        assert L[x] <= R[0];
        assert L[x] <= R[ky];
        assert C[x] <= C[y];
      }
    }
    SortedFromForall(C);
    assert s[..right] == C;
    assert Sorted(s[..right]);
  }
}

lemma {:vcs_split_on_every_assert} SwapPreserves(s: seq<int>, j: int, i: int) returns (t: seq<int>)
  requires 1 <= j <= i < |s|
  requires Sorted(s[..j])
  requires Sorted(s[j..i + 1])
  requires s[j - 1] > s[j]
  requires forall k {:trigger s[k]} :: j < k <= i ==> s[j - 1] <= s[k]
  ensures t == Swapped(s, j - 1, j)
  ensures |t| == |s|
  ensures Sorted(t[..j - 1])
  ensures Sorted(t[j - 1..i + 1])
  ensures multiset(t) == multiset(s)
  ensures forall k {:trigger t[k]} :: j - 1 < k <= i && j > 1 ==> t[j - 2] <= t[k]
{
  var p := j - 1;
  assert j == p + 1;
  t := Swapped(s, p, j);
  SwappedProps(s, p, j);
  SwapMultiset(s, p, j);
  assert t == Swapped(s, p, j);
  assert |t| == |s|;
  assert multiset(t) == multiset(s);

  var sp := s[..p];
  var tp := t[..p];
  forall k | 0 <= k < p
    ensures tp[k] == sp[k]
  {
    assert k != p && k != j;
    assert t[k] == s[k];
    SliceIndex(t, 0, p, k);
    SliceIndex(s, 0, p, k);
    assert tp[k] == t[k];
    assert sp[k] == s[k];
  }
  assert |tp| == p == |sp|;
  SeqEq(tp, sp);

  forall x, y | 0 <= x < y < p
    ensures sp[x] <= sp[y]
  {
    SortedAt(s[..j], x, y);
    SliceIndex(s, 0, j, x);
    SliceIndex(s, 0, j, y);
    SliceIndex(s, 0, p, x);
    SliceIndex(s, 0, p, y);
    assert (s[..j])[x] == s[x];
    assert (s[..j])[y] == s[y];
    assert sp[x] == s[x];
    assert sp[y] == s[y];
  }
  SortedFromForall(sp);
  assert Sorted(tp);
  assert tp == t[..p];
  assert t[..p] == t[..j - 1];
  assert Sorted(t[..j - 1]);

  forall u, v | p <= u < v <= i
    ensures t[u] <= t[v]
  {
    if u == p && v == j {
      assert t[u] == s[j];
      assert t[v] == s[p];
      assert s[p] > s[j];
      assert s[j] <= s[p];
      assert t[u] <= t[v];
    } else if u == p {
      assert j == p + 1;
      assert v != j;
      assert v > p;
      assert v > j;
      assert t[u] == s[j];
      assert v != p && v != j;
      assert t[v] == s[v];
      SuffixAt(s, j, i, j, v);
      assert s[j] <= s[v];
      assert t[u] <= t[v];
    } else if u == j {
      assert v > u;
      assert v > j;
      assert t[u] == s[p];
      assert v != p && v != j;
      assert t[v] == s[v];
      assert s[j - 1] <= s[v];
      assert s[p] <= s[v];
      assert t[u] <= t[v];
    } else {
      assert j == p + 1;
      assert u != p && u != j;
      assert u > p;
      assert u > j;
      assert v > u;
      assert u != p && u != j && v != p && v != j;
      assert t[u] == s[u];
      assert t[v] == s[v];
      SuffixAt(s, j, i, u, v);
      assert t[u] <= t[v];
    }
  }
  assert forall u, v {:trigger t[u], t[v]} :: p <= u < v <= i ==> t[u] <= t[v];

  var suf := t[p..i + 1];
  assert |suf| == i + 1 - p;
  forall x, y | 0 <= x < y < |suf|
    ensures suf[x] <= suf[y]
  {
    var u := p + x;
    var v := p + y;
    assert p <= u < v <= i;
    assert t[u] <= t[v];
    SliceIndex(t, p, i + 1, x);
    SliceIndex(t, p, i + 1, y);
    assert suf[x] == t[u];
    assert suf[y] == t[v];
  }
  SortedFromForall(suf);
  assert suf == t[p..i + 1];
  assert t[p..i + 1] == t[j - 1..i + 1];
  assert Sorted(t[j - 1..i + 1]);

  forall k | j - 1 < k <= i && j > 1
    ensures t[j - 2] <= t[k]
  {
    assert 0 <= j - 2 < |t|;
    assert j - 2 != p && j - 2 != j;
    assert t[j - 2] == s[j - 2];
    SortedAt(s[..j], j - 2, j - 1);
    SliceIndex(s, 0, j, j - 2);
    SliceIndex(s, 0, j, j - 1);
    assert (s[..j])[j - 2] == s[j - 2];
    assert (s[..j])[j - 1] == s[j - 1];
    assert s[j - 2] <= s[j - 1];
    if k == j {
      assert t[k] == s[j - 1];
      assert t[j - 2] <= t[k];
    } else {
      assert k > j;
      assert k != p && k != j;
      assert t[k] == s[k];
      assert s[j - 1] <= s[k];
      assert s[j - 2] <= s[j - 1];
      assert s[j - 2] <= s[k];
      assert t[j - 2] <= t[k];
    }
  }
}

method {:vcs_split_on_every_assert} SwapAdjacent(a: array<int>, j: int)
  requires 1 <= j < a.Length
  modifies a
  ensures a[..] == Swapped(old(a[..]), j - 1, j)
{
  var p := j - 1;
  ghost var pre := a[..];
  var ap := a[p];
  var aj := a[j];
  assert a[..] == pre;
  assert pre == old(a[..]);
  assert ap == pre[p];
  assert aj == pre[j];

  label BeforeP:
  a[p] := aj;
  assert a[..] == old@BeforeP(a[..])[p := aj];
  assert old@BeforeP(a[..]) == pre;
  assert aj == pre[j];
  assert pre[p := aj] == pre[p := pre[j]];
  assert a[..] == pre[p := pre[j]];

  label BeforeJ:
  a[j] := ap;
  assert a[..] == old@BeforeJ(a[..])[j := ap];
  assert old@BeforeJ(a[..]) == pre[p := pre[j]];
  assert ap == pre[p];
  ghost var withAp: seq<int> := (pre[p := pre[j]])[j := ap];
  ghost var withPre: seq<int> := (pre[p := pre[j]])[j := pre[p]];
  assert a[..] == withAp;
  assert withAp == withPre;
  assert a[..] == withPre;
  assert Swapped(pre, p, j) == pre[p := pre[j]][j := pre[p]];
  assert pre[p := pre[j]][j := pre[p]] == withPre;
  assert a[..] == Swapped(pre, p, j);
  assert p == j - 1;
  assert pre == old(a[..]);
  assert a[..] == Swapped(old(a[..]), j - 1, j);
}

method {:vcs_split_on_every_assert} InsertionSort(a: array<int>)
  modifies a
  ensures Sorted(a[..])
  ensures multiset(a[..]) == multiset(old(a[..]))
{
  var i := 0;
  assert |a[..i]| == 0;
  SortedEmptyPrefix(a[..i]);
  assert Sorted(a[..i]);
  assert multiset(a[..]) == multiset(old(a[..]));

  while i < a.Length
    invariant 0 <= i <= a.Length
    invariant Sorted(a[..i])
    invariant multiset(a[..]) == multiset(old(a[..]))
    decreases a.Length - i
  {
    var j := i;
    assert Sorted(a[..j]);
    SortedSingleton(a[..], j);
    ArraySeqSlice(a, j, j + 1);
    assert a[j..j + 1] == (a[..])[j..j + 1];
    assert Sorted((a[..])[j..j + 1]);
    SortedEq((a[..])[j..j + 1], a[j..j + 1]);
    assert j == i;
    assert j + 1 == i + 1;
    assert a[j..i + 1] == a[j..j + 1];
    assert Sorted(a[j..i + 1]);
    assert forall k :: j < k <= i ==> j > 0 ==> a[j - 1] <= a[k];

    while j > 0 && a[j - 1] > a[j]
      invariant 0 <= j <= i < a.Length
      invariant multiset(a[..]) == multiset(old(a[..]))
      invariant Sorted(a[..j])
      invariant Sorted(a[j..i + 1])
      invariant forall k {:trigger a[k]} :: j < k <= i ==> j > 0 ==> a[j - 1] <= a[k]
      decreases j
    {
      ghost var pre := a[..];
      var j0 := j;
      assert pre == a[..];
      assert 1 <= j0 <= i < |pre|;
      EqPrefix(a, j0);
      assert pre[..j0] == a[..j0];
      assert Sorted(a[..j0]);
      SortedEq(a[..j0], pre[..j0]);
      assert Sorted(pre[..j0]);
      ArraySeqSlice(a, j0, i + 1);
      assert a[j0..i + 1] == (a[..])[j0..i + 1];
      assert pre[j0..i + 1] == (a[..])[j0..i + 1];
      assert pre[j0..i + 1] == a[j0..i + 1];
      assert Sorted(a[j0..i + 1]);
      SortedEq(a[j0..i + 1], pre[j0..i + 1]);
      assert Sorted(pre[j0..i + 1]);
      assert pre[j0 - 1] == a[j0 - 1];
      assert pre[j0] == a[j0];
      assert a[j0 - 1] > a[j0];
      assert pre[j0 - 1] > pre[j0];
      forall k | j0 < k <= i
        ensures pre[j0 - 1] <= pre[k]
      {
        assert j0 > 0;
        assert a[j0 - 1] <= a[k];
        assert pre[k] == a[k];
        assert pre[j0 - 1] == a[j0 - 1];
      }
      assert forall k {:trigger pre[k]} :: j0 < k <= i ==> pre[j0 - 1] <= pre[k];
      assert multiset(pre) == multiset(old(a[..]));
      ghost var t := SwapPreserves(pre, j0, i);
      assert t == Swapped(pre, j0 - 1, j0);
      SwapAdjacent(a, j0);
      assert a[..] == Swapped(pre, j0 - 1, j0);
      assert a[..] == t;
      assert multiset(t) == multiset(pre);
      assert multiset(a[..]) == multiset(t);
      assert multiset(a[..]) == multiset(old(a[..]));

      j := j - 1;
      assert j == j0 - 1;
      assert 0 <= j <= i;

      assert Sorted(t[..j0 - 1]);
      assert t[..j] == t[..j0 - 1];
      SortedEq(t[..j0 - 1], t[..j]);
      assert Sorted(t[..j]);
      EqSlice(a[..], t, 0, j);
      assert (a[..])[0..j] == t[0..j];
      assert t[..j] == t[0..j];
      assert (a[..])[..j] == (a[..])[0..j];
      EqPrefix(a, j);
      assert a[..j] == (a[..])[..j];
      assert a[..j] == (a[..])[0..j];
      assert a[..j] == t[..j];
      SortedEq(t[..j], a[..j]);
      assert Sorted(a[..j]);

      assert Sorted(t[j0 - 1..i + 1]);
      assert t[j..i + 1] == t[j0 - 1..i + 1];
      SortedEq(t[j0 - 1..i + 1], t[j..i + 1]);
      EqSlice(a[..], t, j, i + 1);
      ArraySeqSlice(a, j, i + 1);
      assert a[j..i + 1] == (a[..])[j..i + 1];
      assert (a[..])[j..i + 1] == t[j..i + 1];
      assert a[j..i + 1] == t[j..i + 1];
      SortedEq(t[j..i + 1], a[j..i + 1]);
      assert Sorted(a[j..i + 1]);

      forall k | j < k <= i
        ensures j > 0 ==> a[j - 1] <= a[k]
      {
        if j > 0 {
          assert j0 > 1;
          assert j0 - 1 < k <= i;
          assert t[j0 - 2] <= t[k];
          assert j - 1 == j0 - 2;
          assert 0 <= j - 1 < a.Length;
          assert a[j - 1] == (a[..])[j - 1];
          assert (a[..])[j - 1] == t[j - 1];
          assert a[k] == (a[..])[k];
          assert (a[..])[k] == t[k];
          assert a[j - 1] <= a[k];
        }
      }
    }

    if j > 0 {
      assert a[j - 1] <= a[j];
