{
  var L := s[..|s|];
  assert |s[..|s|]| == |s|;
  assert |L| == |s|;
  forall k | 0 <= k < |s|
    ensures L[k] == s[k]
  {
    assert 0 <= k < |L|;
    assert L[k] == s[k];
  }
  assert forall k :: 0 <= k < |L| ==> L[k] == s[k];
  SeqEq(L, s);
  assert L == s;
  assert s[..|s|] == s;
}

lemma {:induction false} {:vcs_split_on_every_assert} SeqTakeAppend(s: seq<int>, i: int)
  requires 0 <= i < |s|
  ensures s[..i + 1] == s[..i] + [s[i]]
{
  var pre := s[..i];
  var L := s[..i + 1];
  var R := pre + [s[i]];
  assert |pre| == i;
  assert |L| == i + 1;
  AppendLast(pre, s[i]);
  assert |R| == i + 1;
  assert |L| == |R|;
  forall k | 0 <= k < |L|
    ensures L[k] == R[k]
  {
    if k < i {
      assert 0 <= k < |pre|;
      assert L[k] == s[k];
      assert pre[k] == s[k];
      assert (pre + [s[i]])[k] == pre[k];
      assert R[k] == pre[k];
      assert R[k] == s[k];
      assert L[k] == R[k];
    } else {
      assert k >= i;
      assert k < i + 1;
      assert k == i;
      assert L[k] == s[i];
      assert (pre + [s[i]])[|pre|] == s[i];
      assert |pre| == i;
      assert R[i] == s[i];
      assert R[k] == s[i];
      assert L[k] == R[k];
    }
  }
  assert forall k :: 0 <= k < |L| ==> L[k] == R[k];
  SeqEq(L, R);
  assert L == R;
  assert s[..i + 1] == s[..i] + [s[i]];
}

