lemma {:induction false} {:vcs_split_on_every_assert} AppendSorted(out: seq<int>, x: int, out': seq<int>)
  requires Sorted(out)
  requires forall k :: 0 <= k < |out| ==> out[k] <= x
  requires out' == out + [x]
  ensures Sorted(out')
{
  AppendLast(out, x);
  assert |out + [x]| == |out| + 1;
  assert |out'| == |out| + 1;
  forall m, n | 0 <= m < n < |out'|
    ensures out'[m] <= out'[n]
  {
    if n < |out| {
      assert 0 <= m < n < |out|;
      assert (out + [x])[m] == out[m];
      assert (out + [x])[n] == out[n];
      assert out'[m] == out[m];
      assert out'[n] == out[n];
      SortedAt(out, m, n);
      assert out[m] <= out[n];
      assert out'[m] <= out'[n];
    } else {
      assert !(n < |out|);
      assert n >= |out|;
      assert n < |out| + 1;
      assert n == |out|;
      assert m < n;
      assert 0 <= m < |out|;
      assert (out + [x])[m] == out[m];
      assert out'[m] == out[m];
      assert out[m] <= x;
      assert (out + [x])[|out|] == x;
      assert out'[n] == x;
      assert out'[m] <= x;
      assert out'[m] <= out'[n];
    }
  }
  assert forall m, n :: 0 <= m < n < |out'| ==> out'[m] <= out'[n];
  assert Sorted(out');
}

lemma {:induction false} {:vcs_split_on_every_assert} LiftBound(out: seq<int>, pivot: int, next: int, out': seq<int>)
  requires out' == out + [pivot]
  requires forall k :: 0 <= k < |out| ==> out[k] <= pivot
  requires pivot <= next
  ensures forall k :: 0 <= k < |out'| ==> out'[k] <= next
{
  AppendLast(out, pivot);
  assert |out'| == |out| + 1;
  forall k | 0 <= k < |out'|
    ensures out'[k] <= next
  {
    if k < |out| {
      assert 0 <= k < |out|;
      assert (out + [pivot])[k] == out[k];
      assert out'[k] == out[k];
      assert out[k] <= pivot;
      assert pivot <= next;
      assert out[k] <= next;
      assert out'[k] <= next;
    } else {
      assert !(k < |out|);
      assert k >= |out|;
      assert k < |out| + 1;
      assert k == |out|;
      assert (out + [pivot])[|out|] == pivot;
      assert out'[k] == pivot;
      assert pivot <= next;
      assert out'[k] <= next;
    }
  }
  assert forall k :: 0 <= k < |out'| ==> out'[k] <= next;
}

lemma {:induction false} {:vcs_split_on_every_assert} TransferLe(s: seq<int>, t: seq<int>, x: int, y: int)
  requires s == t
  requires x == y
  requires forall k :: 0 <= k < |t| ==> t[k] <= y
  ensures forall k :: 0 <= k < |s| ==> s[k] <= x
{
  forall k | 0 <= k < |s|
    ensures s[k] <= x
  {
    assert |s| == |t|;
    assert 0 <= k < |t|;
    assert s[k] == t[k];
    assert t[k] <= y;
    assert y == x;
    assert t[k] <= x;
    assert s[k] <= x;
  }
  assert forall k :: 0 <= k < |s| ==> s[k] <= x;
}

lemma {:induction false} {:vcs_split_on_every_assert} ElseBranch(a: seq<int>, b: seq<int>, i: int, j: int)
  requires 0 <= i <= |a|
  requires 0 <= j <= |b|
  requires i < |a| || j < |b|
  requires !(i < |a| && (j == |b| || a[i] <= b[j]))
  ensures 0 <= j < |b|
  ensures i < |a| ==> b[j] <= a[i]
{
  if j == |b| {
    assert !(j < |b|);
    assert i < |a| || j < |b|;
    assert i < |a|;
    assert j == |b|;
    assert i < |a| && (j == |b| || a[i] <= b[j]);
    assert false;
  }
  assert j != |b|;
  assert 0 <= j <= |b|;
  assert j < |b|;
  if i < |a| {
    assert 0 <= i < |a|;
    assert 0 <= j < |b|;
    assert !(i < |a| && (j == |b| || a[i] <= b[j]));
    assert !(j == |b| || a[i] <= b[j]);
    assert j != |b|;
    assert !(a[i] <= b[j]);
    assert a[i] > b[j];
    assert b[j] <= a[i];
  }
  assert 0 <= j < |b|;
  assert i < |a| ==> b[j] <= a[i];
}

lemma {:induction false} {:vcs_split_on_every_assert} TakeA(
  a: seq<int>, b: seq<int>, out: seq<int>, i: int, j: int, out': seq<int>, i': int
)
  requires Sorted(a) && Sorted(b)
  requires 0 <= i < |a|
  requires 0 <= j <= |b|
  requires j == |b| || a[i] <= b[j]
  requires Sorted(out)
  requires multiset(out) == multiset(a[..i]) + multiset(b[..j])
  requires forall k :: 0 <= k < |out| ==> out[k] <= a[i]
  requires j < |b| ==> forall k :: 0 <= k < |out| ==> out[k] <= b[j]
  requires out' == out + [a[i]]
  requires i' == i + 1
  ensures Sorted(out')
  ensures multiset(out') == multiset(a[..i']) + multiset(b[..j])
  ensures i' < |a| ==> forall k :: 0 <= k < |out'| ==> out'[k] <= a[i']
  ensures j < |b| ==> forall k :: 0 <= k < |out'| ==> out'[k] <= b[j]
{
  AppendSorted(out, a[i], out');
  assert Sorted(out');

  var ma := multiset(a[..i]);
  var mb := multiset(b[..j]);
  var mx := multiset{a[i]};
  MultisetSingletonAppend(out, a[i]);
  assert multiset(out + [a[i]]) == multiset(out) + multiset{a[i]};
  assert multiset{a[i]} == mx;
  assert multiset(out + [a[i]]) == multiset(out) + mx;
  assert out' == out + [a[i]];
  assert multiset(out') == multiset(out + [a[i]]);
  assert multiset(out') == multiset(out) + mx;
  assert multiset(out) == ma + mb;
  assert multiset(out) + mx == (ma + mb) + mx;
  assert multiset(out') == (ma + mb) + mx;
  MRearrange(ma, mb, mx);
  assert (ma + mb) + mx == (ma + mx) + mb;
  assert multiset(out') == (ma + mx) + mb;
  MultisetTakeStep(a, i);
  assert multiset(a[..i + 1]) == multiset(a[..i]) + multiset{a[i]};
  assert multiset(a[..i]) == ma;
  assert multiset(a[..i + 1]) == ma + mx;
  assert i' == i + 1;
  assert a[..i'] == a[..i + 1];
  assert multiset(a[..i']) == multiset(a[..i + 1]);
  assert multiset(a[..i']) == ma + mx;
  assert (ma + mx) + mb == multiset(a[..i']) + mb;
  assert multiset(out') == multiset(a[..i']) + mb;
  assert mb == multiset(b[..j]);
  assert multiset(a[..i']) + mb == multiset(a[..i']) + multiset(b[..j]);
  assert multiset(out') == multiset(a[..i']) + multiset(b[..j]);

  if i' < |a| {
    assert i' == i + 1;
    assert i + 1 < |a|;
    assert 0 <= i < |a| - 1;
    SortedAdjacent(a, i);
    assert a[i] <= a[i + 1];
    assert a[i + 1] == a[i'];
    assert a[i] <= a[i'];
    LiftBound(out, a[i], a[i'], out');
    assert forall k :: 0 <= k < |out'| ==> out'[k] <= a[i'];
  }
  if j < |b| {
    assert j != |b|;
    assert j == |b| || a[i] <= b[j];
    assert a[i] <= b[j];
    LiftBound(out, a[i], b[j], out');
    assert forall k :: 0 <= k < |out'| ==> out'[k] <= b[j];
  }
  assert Sorted(out');
  assert multiset(out') == multiset(a[..i']) + multiset(b[..j]);
  assert i' < |a| ==> forall k :: 0 <= k < |out'| ==> out'[k] <= a[i'];
  assert j < |b| ==> forall k :: 0 <= k < |out'| ==> out'[k] <= b[j];
}

lemma {:induction false} {:vcs_split_on_every_assert} TakeB(
  a: seq<int>, b: seq<int>, out: seq<int>, i: int, j: int, out': seq<int>, j': int
)
  requires Sorted(a) && Sorted(b)
  requires 0 <= i <= |a|
  requires 0 <= j < |b|
  requires i < |a| ==> b[j] <= a[i]
  requires Sorted(out)
  requires multiset(out) == multiset(a[..i]) + multiset(b[..j])
  requires i < |a| ==> forall k :: 0 <= k < |out| ==> out[k] <= a[i]
  requires forall k :: 0 <= k < |out| ==> out[k] <= b[j]
  requires out' == out + [b[j]]
  requires j' == j + 1
  ensures Sorted(out')
  ensures multiset(out') == multiset(a[..i]) + multiset(b[..j'])
  ensures i < |a| ==> forall k :: 0 <= k < |out'| ==> out'[k] <= a[i]
  ensures j' < |b| ==> forall k :: 0 <= k < |out'| ==> out'[k] <= b[j']
{
  AppendSorted(out, b[j], out');
  assert Sorted(out');

  var ma := multiset(a[..i]);
  var mb := multiset(b[..j]);
  var mx := multiset{b[j]};
  MultisetSingletonAppend(out, b[j]);
  assert multiset(out + [b[j]]) == multiset(out) + multiset{b[j]};
  assert multiset{b[j]} == mx;
  assert multiset(out + [b[j]]) == multiset(out) + mx;
  assert out' == out + [b[j]];
  assert multiset(out') == multiset(out + [b[j]]);
  assert multiset(out') == multiset(out) + mx;
  assert multiset(out) == ma + mb;
  assert multiset(out) + mx == (ma + mb) + mx;
  assert multiset(out') == (ma + mb) + mx;
  MAssoc(ma, mb, mx);
  assert (ma + mb) + mx == ma + (mb + mx);
  assert multiset(out') == ma + (mb + mx);
  MultisetTakeStep(b, j);
  assert multiset(b[..j + 1]) == multiset(b[..j]) + multiset{b[j]};
  assert multiset(b[..j]) == mb;
  assert multiset(b[..j + 1]) == mb + mx;
  assert mb + mx == multiset(b[..j + 1]);
  assert ma + (mb + mx) == ma + multiset(b[..j + 1]);
  assert multiset(out') == ma + multiset(b[..j + 1]);
  assert j' == j + 1;
  assert b[..j'] == b[..j + 1];
  assert multiset(b[..j']) == multiset(b[..j + 1]);
  assert ma + multiset(b[..j + 1]) == ma + multiset(b[..j']);
  assert multiset(out') == ma + multiset(b[..j']);
  assert ma == multiset(a[..i]);
  assert multiset(out') == multiset(a[..i]) + multiset(b[..j']);

  if i < |a| {
    assert b[j] <= a[i];
    LiftBound(out, b[j], a[i], out');
    assert forall k :: 0 <= k < |out'| ==> out'[k] <= a[i];
  }
  if j' < |b| {
    assert j' == j + 1;
    assert j + 1 < |b|;
    assert 0 <= j < |b| - 1;
    SortedAdjacent(b, j);
    assert b[j] <= b[j + 1];
    assert b[j + 1] == b[j'];
    assert b[j] <= b[j'];
    LiftBound(out, b[j], b[j'], out');
    assert forall k :: 0 <= k < |out'| ==> out'[k] <= b[j'];
  }
  assert Sorted(out');
  assert multiset(out') == multiset(a[..i]) + multiset(b[..j']);
  assert i < |a| ==> forall k :: 0 <= k < |out'| ==> out'[k] <= a[i];
  assert j' < |b| ==> forall k :: 0 <= k < |out'| ==> out'[k] <= b[j'];
}

method {:vcs_split_on_every_assert} MergeSorted(a: seq<int>, b: seq<int>) returns (out: seq<int>)
  requires Sorted(a) && Sorted(b)
  ensures Sorted(out)
  ensures multiset(out) == multiset(a) + multiset(b)
{
  out := [];
  var i := 0;
  var j := 0;

  SortedEmpty(out);
  SliceEmpty(a);
  SliceEmpty(b);
  assert out == [];
  assert |out| == 0;
  assert Sorted(out);
  assert i == 0 && j == 0;
  assert a[..0] == [];
  assert b[..0] == [];
  assert a[..i] == [];
  assert b[..j] == [];

  ghost var emptySeq: seq<int> := [];
  ghost var emptyMs: multiset<int> := multiset{};
  assert multiset(emptySeq) == emptyMs;
  assert out == emptySeq;
  assert multiset(out) == multiset(emptySeq);
  assert multiset(out) == emptyMs;
  assert a[..i] == emptySeq;
  assert b[..j] == emptySeq;
  assert multiset(a[..i]) == emptyMs;
  assert multiset(b[..j]) == emptyMs;
  assert emptyMs + emptyMs == emptyMs;
  assert multiset(a[..i]) + multiset(b[..j]) == emptyMs;
  assert multiset(out) == multiset(a[..i]) + multiset(b[..j]);
  assert 0 <= i <= |a|;
  assert 0 <= j <= |b|;
  assert i < |a| ==> forall k :: 0 <= k < |out| ==> out[k] <= a[i];
  assert j < |b| ==> forall k :: 0 <= k < |out| ==> out[k] <= b[j];

  while i < |a| || j < |b|
    invariant 0 <= i <= |a|
    invariant 0 <= j <= |b|
    invariant Sorted(out)
    invariant multiset(out) == multiset(a[..i]) + multiset(b[..j])
    invariant i < |a| ==> forall k :: 0 <= k < |out| ==> out[k] <= a[i]
    invariant j < |b| ==> forall k :: 0 <= k < |out| ==> out[k] <= b[j]
    decreases |a| + |b| - i - j
  {
    if i < |a| && (j == |b| || a[i] <= b[j]) {
      assert 0 <= i < |a|;
      assert 0 <= j <= |b|;
      assert j == |b| || a[i] <= b[j];
      assert Sorted(out);
      assert multiset(out) == multiset(a[..i]) + multiset(b[..j]);
      assert forall k :: 0 <= k < |out| ==> out[k] <= a[i];
      assert j < |b| ==> forall k :: 0 <= k < |out| ==> out[k] <= b[j];
      var out1 := out + [a[i]];
      var i1 := i + 1;
      assert out1 == out + [a[i]];
      assert i1 == i + 1;
      TakeA(a, b, out, i, j, out1, i1);
      assert Sorted(out1);
      assert multiset(out1) == multiset(a[..i1]) + multiset(b[..j]);
      assert i1 < |a| ==> forall k :: 0 <= k < |out1| ==> out1[k] <= a[i1];
      assert j < |b| ==> forall k :: 0 <= k < |out1| ==> out1[k] <= b[j];
      out := out1;
      i := i1;
      assert out == out1;
      assert i == i1;
      assert Sorted(out);
      assert a[..i] == a[..i1];
      assert multiset(a[..i]) == multiset(a[..i1]);
      assert multiset(a[..i]) + multiset(b[..j]) == multiset(a[..i1]) + multiset(b[..j]);
      assert multiset(out1) == multiset(a[..i]) + multiset(b[..j]);
      assert multiset(out) == multiset(out1);
      assert multiset(out) == multiset(a[..i]) + multiset(b[..j]);
      if i < |a| {
        assert i1 < |a|;
        assert forall k :: 0 <= k < |out1| ==> out1[k] <= a[i1];
        assert a[i] == a[i1];
        TransferLe(out, out1, a[i], a[i1]);
        assert forall k :: 0 <= k < |out| ==> out[k] <= a[i];
      }
      if j < |b| {
        assert forall k :: 0 <= k < |out1| ==> out1[k] <= b[j];
        TransferLe(out, out1, b[j], b[j]);
        assert forall k :: 0 <= k < |out| ==> out[k] <= b[j];
      }
      assert 0 <= i <= |a|;
      assert 0 <= j <= |b|;
      assert Sorted(out);
      assert multiset(out) == multiset(a[..i]) + multiset(b[..j]);
      assert i < |a| ==> forall k :: 0 <= k < |out| ==> out[k] <= a[i];
      assert j < |b| ==> forall k :: 0 <= k < |out| ==> out[k] <= b[j];
    } else {
      assert !(i < |a| && (j == |b| || a[i] <= b[j]));
      assert i < |a| || j < |b|;
      assert 0 <= i <= |a|;
      assert 0 <= j <= |b|;
      ElseBranch(a, b, i, j);
      assert 0 <= j < |b|;
      assert i < |a| ==> b[j] <= a[i];
      assert Sorted(out);
      assert multiset(out) == multiset(a[..i]) + multiset(b[..j]);
      assert i < |a| ==> forall k :: 0 <= k < |out| ==> out[k] <= a[i];
      assert forall k :: 0 <= k < |out| ==> out[k] <= b[j];
      var out1 := out + [b[j]];
      var j1 := j + 1;
      assert out1 == out + [b[j]];
      assert j1 == j + 1;
      TakeB(a, b, out, i, j, out1, j1);
      assert Sorted(out1);
      assert multiset(out1) == multiset(a[..i]) + multiset(b[..j1]);
      assert i < |a| ==> forall k :: 0 <= k < |out1| ==> out1[k] <= a[i];
      assert j1 < |b| ==> forall k :: 0 <= k < |out1| ==> out1[k] <= b[j1];
      out := out1;
      j := j1;
      assert out == out1;
      assert j == j1;
      assert Sorted(out);
      assert b[..j] == b[..j1];
      assert multiset(b[..j]) == multiset(b[..j1]);
      assert multiset(a[..i]) + multiset(b[..j]) == multiset(a[..i]) + multiset(b[..j1]);
      assert multiset(out1) == multiset(a[..i]) + multiset(b[..j]);
      assert multiset(out) == multiset(out1);
      assert multiset(out) == multiset(a[..i]) + multiset(b[..j]);
      if i < |a| {
        assert forall k :: 0 <= k < |out1| ==> out1[k] <= a[i];
        TransferLe(out, out1, a[i], a[i]);
        assert forall k :: 0 <= k < |out| ==> out[k] <= a[i];
      }
      if j < |b| {
        assert j == j1;
        assert j1 < |b|;
        assert forall k :: 0 <= k < |out1| ==> out1[k] <= b[j1];
        assert b[j] == b[j1];
        TransferLe(out, out1, b[j], b[j1]);
        assert forall k :: 0 <= k < |out| ==> out[k] <= b[j];
      }
      assert 0 <= i <= |a|;
      assert 0 <= j <= |b|;
      assert Sorted(out);
      assert multiset(out) == multiset(a[..i]) + multiset(b[..j]);
      assert i < |a| ==> forall k :: 0 <= k < |out| ==> out[k] <= a[i];
      assert j < |b| ==> forall k :: 0 <= k < |out| ==> out[k] <= b[j];
