  forall k | 0 <= k < |s|
    ensures u[k] == v[k]
  {
    SwappedIndex(s, i, j, k);
    SwappedIndex(s, j, i, k);
    if k == i && k == j {
      assert u[k] == s[j];
      assert v[k] == s[i];
      assert s[i] == s[j];
    } else if k == i {
      assert i != j;
      assert u[k] == s[j];
      assert v[k] == s[j];
    } else if k == j {
      assert j != i;
      assert u[k] == s[i];
      assert v[k] == s[i];
    } else {
      assert u[k] == s[k];
      assert v[k] == s[k];
    }
  }
  assert |u| == |s|;
  assert |v| == |s|;
  SeqExt(u, v);
