lemma {:induction false} {:vcs_split_on_every_assert} SeqParts(s: seq<int>, i: int, j: int)
  requires 0 <= i < j < |s|
  ensures s == s[..i] + [s[i]] + s[i+1..j] + [s[j]] + s[j+1..]
{
  var a := s[..i];
  var b := [s[i]];
  var c := s[i+1..j];
  var d := [s[j]];
  var e := s[j+1..];
