  var abc := ab + c;
  var abcd := abc + d;
  var whole := abcd + e;

  assert 0 <= i + 1 <= j <= |s|;
  assert j + 1 <= |s|;
  assert |a| == i;
  assert |b| == 1;
  assert |c| == j - (i + 1);
  assert j - (i + 1) == j - i - 1;
  assert |d| == 1;
  assert |e| == |s| - (j + 1);
  assert |ab| == |a| + |b| == i + 1;
  assert |abc| == |ab| + |c|;
  assert |abc| == (i + 1) + (j - i - 1) == j;
  assert |abcd| == |abc| + |d| == j + 1;
  assert |whole| == |abcd| + |e|;
  assert |whole| == (j + 1) + (|s| - (j + 1)) == |s|;

  forall k | 0 <= k < |s|
    ensures whole[k] == s[k]
  {
    if k < i {
      assert 0 <= k < |a|;
      assert a[k] == s[k];
      assert ab[k] == a[k];
      assert 0 <= k < |ab|;
      assert abc[k] == ab[k];
      assert 0 <= k < |abc|;
      assert abcd[k] == abc[k];
      assert 0 <= k < |abcd|;
      assert whole[k] == abcd[k];
    } else if k == i {
      assert |a| == k;
      assert ab[k] == b[0];
      assert b[0] == s[i];
      assert 0 <= k < |ab|;
      assert abc[k] == ab[k];
      assert 0 <= k < |abc|;
      assert abcd[k] == abc[k];
      assert 0 <= k < |abcd|;
      assert whole[k] == abcd[k];
    } else if k < j {
      assert i < k;
      var m := k - (i + 1);
      assert 0 <= m < |c|;
      assert |ab| == i + 1;
      assert abc[k] == c[m];
      assert c[m] == s[(i + 1) + m];
      assert (i + 1) + m == k;
      assert 0 <= k < |abc|;
      assert abcd[k] == abc[k];
      assert 0 <= k < |abcd|;
      assert whole[k] == abcd[k];
      assert whole[k] == s[k];
    } else if k == j {
      assert |abc| == k;
      assert abcd[k] == d[0];
      assert d[0] == s[j];
      assert 0 <= k < |abcd|;
      assert whole[k] == abcd[k];
    } else {
      assert j < k;
      var m := k - (j + 1);
      assert |abcd| == j + 1;
      assert 0 <= m < |e|;
      assert whole[k] == e[m];
      assert e[m] == s[(j + 1) + m];
      assert (j + 1) + m == k;
    }
  }
  SeqExt(whole, s);
  assert whole == s[..i] + [s[i]] + s[i+1..j] + [s[j]] + s[j+1..];
}

lemma {:induction false} {:vcs_split_on_every_assert} SwappedParts(s: seq<int>, i: int, j: int)
  requires 0 <= i < j < |s|
  ensures Swapped(s, i, j) == s[..i] + [s[j]] + s[i+1..j] + [s[i]] + s[j+1..]
