lemma {:induction false} {:vcs_split_on_every_assert} MS5Count(
  a: seq<int>, b: seq<int>, c: seq<int>, d: seq<int>, e: seq<int>, x: int
)
  ensures multiset(a + b + c + d + e)[x]
       == (((multiset(a)[x] + multiset(b)[x]) + multiset(c)[x]) + multiset(d)[x]) + multiset(e)[x]
{
