  MSConcat(ab, c);
  assert multiset(abc) == (multiset(a) + multiset(b)) + multiset(c);
  MSConcat(abc, d);
  assert multiset(abcd) == ((multiset(a) + multiset(b)) + multiset(c)) + multiset(d);
  MSConcat(abcd, e);
  assert multiset(abcde) == (((multiset(a) + multiset(b)) + multiset(c)) + multiset(d)) + multiset(e);

  var ma := multiset(a);
  var mb := multiset(b);
  var mc := multiset(c);
  var md := multiset(d);
  var me := multiset(e);
  MSCardPlus(ma, mb, x);
  MSCardPlus(ma + mb, mc, x);
  MSCardPlus((ma + mb) + mc, md, x);
  MSCardPlus(((ma + mb) + mc) + md, me, x);
  assert multiset(abcde)[x] == ((((ma + mb) + mc) + md) + me)[x];
