lemma {:induction false} {:vcs_split_on_every_assert} SwapMultisetLt(s: seq<int>, i: int, j: int)
  requires 0 <= i < j < |s|
  ensures multiset(Swapped(s, i, j)) == multiset(s)
{
  var left := s[..i];
  var Aseq := [s[i]];
  var mid := s[i+1..j];
  var Bseq := [s[j]];
  var right := s[j+1..];
  var u := Swapped(s, i, j);

  SeqParts(s, i, j);
  assert s == left + Aseq + mid + Bseq + right;
  SwappedParts(s, i, j);
  assert u == left + Bseq + mid + Aseq + right;

  forall x: int
    ensures multiset(s)[x] == multiset(u)[x]
  {
    MS5Count(left, Aseq, mid, Bseq, right, x);
    MS5Count(left, Bseq, mid, Aseq, right, x);
    var p := multiset(left)[x];
    var q := multiset(Aseq)[x];
    var r := multiset(mid)[x];
    var bv := multiset(Bseq)[x];
    var w := multiset(right)[x];
    assert multiset(s)[x] == (((p + q) + r) + bv) + w;
    assert multiset(u)[x] == (((p + bv) + r) + q) + w;
    assert (((p + q) + r) + bv) + w == (((p + bv) + r) + q) + w;
  }
  MultisetExt(s, u);
}

lemma {:induction false} SwapMultiset(s: seq<int>, i: int, j: int)
  requires 0 <= i < |s|
  requires 0 <= j < |s|
  ensures multiset(Swapped(s, i, j)) == multiset(s)
{
  if i == j {
    SwappedId(s, i);
    assert multiset(Swapped(s, i, j)) == multiset(s);
  } else if i < j {
    SwapMultisetLt(s, i, j);
  } else {
    assert j < i;
    SwappedSym(s, i, j);
    SwapMultisetLt(s, j, i);
    assert Swapped(s, i, j) == Swapped(s, j, i);
    assert multiset(Swapped(s, i, j)) == multiset(s);
  }
}

