        assert Swapped(olds, i, j)[k] == olds[j];
      } else if k == j {
        assert a[k] == ai;
        assert ai == olds[i];
        assert Swapped(olds, i, j)[k] == olds[i];
      } else {
        assert a[k] == olds[k];
        assert Swapped(olds, i, j)[k] == olds[k];
