method {:vcs_split_on_every_assert} Partition(a: array<int>, pivot: int) returns (k: int)
  modifies a
  ensures 0 <= k <= a.Length
  ensures forall i :: 0 <= i < k ==> a[i] < pivot
  ensures forall i :: k <= i < a.Length ==> a[i] >= pivot
  ensures multiset(a[..]) == multiset(old(a[..]))
{
  k := 0;
  var j := 0;
  while j < a.Length
    invariant 0 <= k <= j <= a.Length
    invariant forall i :: 0 <= i < k ==> a[i] < pivot
    invariant forall i :: k <= i < j ==> a[i] >= pivot
    invariant multiset(a[..]) == multiset(old(a[..]))
    decreases a.Length - j
  {
    var oldk := k;
    var oldj := j;
    ghost var pre := a[..];
    assert pre == a[..];
    assert |pre| == a.Length;

    forall i | 0 <= i < oldk
      ensures pre[i] < pivot
    {
      assert pre[i] == a[i];
      assert a[i] < pivot;
    }
    forall i | oldk <= i < oldj
      ensures pre[i] >= pivot
    {
      assert pre[i] == a[i];
      assert a[i] >= pivot;
    }
    assert multiset(pre) == multiset(old(a[..]));

    if a[oldj] < pivot {
      assert pre[oldj] == a[oldj];
      assert pre[oldj] < pivot;
      Swap(a, oldk, oldj);
      assert a[..] == Swapped(pre, oldk, oldj);
      assert multiset(a[..]) == multiset(pre);
      k := oldk + 1;
      j := oldj + 1;
      assert 0 <= k <= j <= a.Length;
      assert a[..] == Swapped(pre, oldk, oldj);

      forall i | 0 <= i < k
        ensures a[i] < pivot
      {
        assert a[i] == a[..][i];
        assert a[..][i] == Swapped(pre, oldk, oldj)[i];
        SwappedIndex(pre, oldk, oldj, i);
        if i < oldk {
          assert i != oldk && i != oldj;
          assert (if i == oldk then pre[oldj] else if i == oldj then pre[oldk] else pre[i]) == pre[i];
          assert Swapped(pre, oldk, oldj)[i] == pre[i];
          assert pre[i] < pivot;
        } else {
          assert i == oldk;
          assert Swapped(pre, oldk, oldj)[i] == pre[oldj];
          assert pre[oldj] < pivot;
        }
      }

      forall i | k <= i < j
        ensures a[i] >= pivot
      {
        assert oldk + 1 <= i <= oldj;
        assert a[i] == a[..][i];
        assert a[..] == Swapped(pre, oldk, oldj);
        assert a[..][i] == Swapped(pre, oldk, oldj)[i];
        SwappedIndex(pre, oldk, oldj, i);
        if i == oldj {
          assert i != oldk;
          assert oldk < oldj;
          assert Swapped(pre, oldk, oldj)[i] == pre[oldk];
          assert oldk <= oldk < oldj;
          assert pre[oldk] >= pivot;
        } else {
          assert i != oldk && i != oldj;
          assert oldk <= i < oldj;
          assert (if i == oldk then pre[oldj] else if i == oldj then pre[oldk] else pre[i]) == pre[i];
          assert Swapped(pre, oldk, oldj)[i] == pre[i];
          assert pre[i] >= pivot;
        }
      }
      assert multiset(a[..]) == multiset(old(a[..]));
    } else {
      assert pre[oldj] == a[oldj];
      assert !(pre[oldj] < pivot);
      assert pre[oldj] >= pivot;
      assert a[..] == pre;
      j := oldj + 1;
      assert k == oldk;
      assert 0 <= k <= j <= a.Length;
      assert a[..] == pre;

      forall i | 0 <= i < k
        ensures a[i] < pivot
      {
        assert i < oldk;
        assert a[i] == pre[i];
        assert pre[i] < pivot;
      }

      forall i | k <= i < j
        ensures a[i] >= pivot
      {
        assert a[i] == pre[i];
        if i < oldj {
          assert oldk <= i < oldj;
          assert pre[i] >= pivot;
        } else {
          assert i == oldj;
          assert pre[oldj] >= pivot;
        }
      }
      assert multiset(a[..]) == multiset(pre);
      assert multiset(a[..]) == multiset(old(a[..]));
    }
  }
  assert j == a.Length;
}
