  requires forall n {:trigger pre[n]} :: oldk <= n < oj ==> pre[n] >= pivot
  requires pre[oj] < pivot
  ensures forall n {:trigger Swapped(pre, oldk, oj)[n]} :: 0 <= n < oldk + 1 ==> Swapped(pre, oldk, oj)[n] < pivot
  ensures forall n {:trigger Swapped(pre, oldk, oj)[n]} :: oldk + 1 <= n < oj + 1 ==> Swapped(pre, oldk, oj)[n] >= pivot
  ensures multiset(Swapped(pre, oldk, oj)) == multiset(pre)
{
  var post := Swapped(pre, oldk, oj);
  assert post == (pre[oldk := pre[oj]])[oj := pre[oldk]];
  SwapIndex(pre, oldk, oj);
  SwapMs(pre, oldk, oj);
  assert multiset((pre[oldk := pre[oj]])[oj := pre[oldk]]) == multiset(pre);
  assert multiset(post) == multiset(pre);
  assert Swapped(pre, oldk, oj)[oldk] == pre[oj];
  assert Swapped(pre, oldk, oj)[oj] == pre[oldk];
  assert post[oldk] == pre[oj];
  assert post[oj] == pre[oldk];

  forall n | 0 <= n < |pre| && n != oldk && n != oj
    ensures post[n] == pre[n]
  {
    assert Swapped(pre, oldk, oj)[n] == pre[n];
    assert post[n] == Swapped(pre, oldk, oj)[n];
  }

  forall n | 0 <= n < oldk + 1
    ensures post[n] < pivot
  {
    if n < oldk {
      assert n != oldk;
      assert n != oj;
      assert post[n] == pre[n];
      assert pre[n] < pivot;
    } else {
      assert n == oldk;
      assert post[n] == pre[oj];
      assert pre[oj] < pivot;
    }
  }

  forall n | oldk + 1 <= n < oj + 1
    ensures post[n] >= pivot
  {
    assert oldk + 1 <= n < oj + 1;
    assert oldk < oj;
    if n == oj {
      assert post[oj] == pre[oldk];
      assert oldk <= oldk < oj;
      assert pre[oldk] >= pivot;
    } else {
      assert n != oj;
      assert n != oldk;
      assert oldk < n < oj;
      assert post[n] == pre[n];
      assert pre[n] >= pivot;
