      assert 0 <= n - 1 < |rest|;
      assert rest[n - 1] == s[n];
    }
  }
  assert forall n :: 0 <= n < |t| ==> t[n] == r[n];
  SeqExt(t, r);
}

lemma HeadTail(s: seq<int>)
  requires |s| >= 1
  ensures s == [s[0]] + s[1..]
{
  UpdateSame(s, 0);
  UpdateHead(s, s[0]);
  assert s[0 := s[0]] == s;
  assert s[0 := s[0]] == [s[0]] + s[1..];
  assert s == [s[0]] + s[1..];
}

lemma TailOfCons(h: int, r: seq<int>)
  ensures ([h] + r)[0] == h
  ensures ([h] + r)[1..] == r
{
  var s := [h] + r;
  assert s[0] == h;
  var tail := s[1..];
  assert |tail| == |r|;
  forall n | 0 <= n < |r|
    ensures tail[n] == r[n]
  {
    assert 0 <= n + 1 < |s|;
    assert tail[n] == s[n + 1];
    assert s[n + 1] == r[n];
  }
  assert forall n :: 0 <= n < |tail| ==> tail[n] == r[n];
  SeqExt(tail, r);
}

lemma UpdateTail(s: seq<int>, i: int, v: int)
  requires 1 <= i < |s|
  ensures s[i := v] == [s[0]] + (s[1..])[i - 1 := v]
{
  var tail := s[1..];
  var tail2 := tail[i - 1 := v];
  var t := s[i := v];
  var r := [s[0]] + tail2;
  assert |tail| == |s| - 1;
  assert 0 <= i - 1 < |tail|;
  UpdateAt(tail, i - 1, v);
  assert |tail2| == |tail|;
  assert |t| == |s|;
  assert |r| == |s|;
  forall n | 0 <= n < |s|
    ensures t[n] == r[n]
  {
    if n == 0 {
      assert t[0] == s[0];
      assert r[0] == s[0];
    } else if n == i {
      UpdateAt(s, i, v);
      assert t[n] == v;
      assert 0 <= n - 1 < |tail2|;
      assert r[n] == tail2[n - 1];
      assert n - 1 == i - 1;
      assert tail2[i - 1] == v;
      assert r[n] == v;
    } else {
      UpdateOther(s, i, n, v);
      assert t[n] == s[n];
      assert 0 <= n - 1 < |tail|;
      assert n - 1 != i - 1;
      UpdateOther(tail, i - 1, n - 1, v);
      assert tail2[n - 1] == tail[n - 1];
      assert tail[n - 1] == s[n];
      assert 0 <= n - 1 < |tail2|;
      assert r[n] == tail2[n - 1];
      assert r[n] == s[n];
    }
  }
  assert forall n :: 0 <= n < |t| ==> t[n] == r[n];
  SeqExt(t, r);
}

lemma OccursUpdate(s: seq<int>, i: int, v: int, x: int)
  requires 0 <= i < |s|
  ensures Occurs(s[i := v], x) == Occurs(s, x) - (if s[i] == x then 1 else 0) + (if v == x then 1 else 0)
  decreases |s|
{
  if i == 0 {
    UpdateHead(s, v);
    var t := s[0 := v];
    var rest := s[1..];
    assert t == [v] + rest;
    TailOfCons(v, rest);
    assert t[0] == v;
    assert t[1..] == rest;
    assert Occurs(t, x) == Occurs(rest, x) + (if v == x then 1 else 0);
    assert Occurs(s, x) == Occurs(rest, x) + (if s[0] == x then 1 else 0);
    if s[0] == x {
      assert Occurs(s, x) == Occurs(rest, x) + 1;
      assert Occurs(t, x) == Occurs(s, x) - 1 + (if v == x then 1 else 0);
    } else {
      assert Occurs(s, x) == Occurs(rest, x);
      assert Occurs(t, x) == Occurs(s, x) + (if v == x then 1 else 0);
    }
    assert Occurs(t, x) == Occurs(s, x) - (if s[0] == x then 1 else 0) + (if v == x then 1 else 0);
  } else {
    var tail := s[1..];
    assert |tail| == |s| - 1;
    assert 0 <= i - 1 < |tail|;
    assert tail[i - 1] == s[i];
    OccursUpdate(tail, i - 1, v, x);
    var tail2 := tail[i - 1 := v];
    UpdateTail(s, i, v);
    var t := s[i := v];
    assert t == [s[0]] + tail2;
    TailOfCons(s[0], tail2);
    assert t[0] == s[0];
    assert t[1..] == tail2;
    assert Occurs(t, x) == Occurs(tail2, x) + (if s[0] == x then 1 else 0);
    assert Occurs(s, x) == Occurs(tail, x) + (if s[0] == x then 1 else 0);
    assert Occurs(tail2, x) == Occurs(tail, x) - (if tail[i - 1] == x then 1 else 0) + (if v == x then 1 else 0);
    var dh := if s[0] == x then 1 else 0;
    var di := if s[i] == x then 1 else 0;
    var dv := if v == x then 1 else 0;
    assert (if tail[i - 1] == x then 1 else 0) == di;
    assert (if s[0] == x then 1 else 0) == dh;
    assert (if v == x then 1 else 0) == dv;
    var ctail := Occurs(tail, x);
    var ctail2 := Occurs(tail2, x);
    var cs := Occurs(s, x);
    var ct := Occurs(t, x);
    assert ctail2 == ctail - di + dv;
    assert ct == ctail2 + dh;
    assert ct == ctail - di + dv + dh;
    assert cs == ctail + dh;
    assert cs - di + dv == ctail + dh - di + dv;
    assert ct == cs - di + dv;
    assert ct == cs - (if s[i] == x then 1 else 0) + (if v == x then 1 else 0);
  }
}

lemma DoubleUpdateSame(s: seq<int>, i: int)
  requires 0 <= i < |s|
  ensures (s[i := s[i]])[i := s[i]] == s
{
  UpdateSame(s, i);
  var t := s[i := s[i]];
  assert t == s;
  assert t[i] == s[i];
  UpdateSame(t, i);
  assert (t[i := t[i]]) == t;
  assert (t[i := s[i]]) == (t[i := t[i]]);
  assert (t[i := s[i]]) == s;
  assert (s[i := s[i]])[i := s[i]] == (t[i := s[i]]);
}

lemma OccursEqMultiset(s: seq<int>, x: int)
  ensures Occurs(s, x) == multiset(s)[x]
  decreases |s|
{
  if |s| == 0 {
    assert s == [];
    assert Occurs(s, x) == 0;
    assert multiset([])[x] == 0;
    assert multiset(s)[x] == 0;
  } else {
    OccursEqMultiset(s[1..], x);
    HeadTail(s);
    assert s == [s[0]] + s[1..];
    assert multiset(s) == multiset([s[0]] + s[1..]);
    assert multiset([s[0]] + s[1..]) == multiset([s[0]]) + multiset(s[1..]);
    assert multiset([s[0]]) == multiset{s[0]};
    assert multiset(s) == multiset{s[0]} + multiset(s[1..]);
    assert (multiset{s[0]} + multiset(s[1..]))[x] == multiset{s[0]}[x] + multiset(s[1..])[x];
    assert multiset(s)[x] == multiset{s[0]}[x] + multiset(s[1..])[x];
    assert multiset{s[0]}[x] == (if s[0] == x then 1 else 0);
    if s[0] == x {
      assert multiset{s[0]}[x] == 1;
      assert multiset(s)[x] == multiset(s[1..])[x] + 1;
      assert Occurs(s, x) == Occurs(s[1..], x) + 1;
      assert Occurs(s, x) == multiset(s)[x];
    } else {
      assert multiset{s[0]}[x] == 0;
      assert multiset(s)[x] == multiset(s[1..])[x];
      assert Occurs(s, x) == Occurs(s[1..], x);
      assert Occurs(s, x) == multiset(s)[x];
    }
  }
}

lemma OccursSwap(s: seq<int>, i: int, j: int, x: int)
  requires 0 <= i < |s|
  requires 0 <= j < |s|
  ensures Occurs((s[i := s[j]])[j := s[i]], x) == Occurs(s, x)
{
  if i == j {
    DoubleUpdateSame(s, i);
    assert s[j] == s[i];
    assert (s[i := s[j]])[j := s[i]] == (s[i := s[i]])[i := s[i]];
    assert (s[i := s[i]])[i := s[i]] == s;
    assert Occurs((s[i := s[j]])[j := s[i]], x) == Occurs(s, x);
  } else {
    var si := s[i];
    var sj := s[j];
    OccursUpdate(s, i, sj, x);
    var s1 := s[i := sj];
    UpdateOther(s, i, j, sj);
    assert s1[j] == sj;
    OccursUpdate(s1, j, si, x);
    var s2 := s1[j := si];
    var di := if si == x then 1 else 0;
    var dj := if sj == x then 1 else 0;
    assert Occurs(s1, x) == Occurs(s, x) - (if s[i] == x then 1 else 0) + (if sj == x then 1 else 0);
    assert (if s[i] == x then 1 else 0) == di;
    assert (if sj == x then 1 else 0) == dj;
    assert Occurs(s1, x) == Occurs(s, x) - di + dj;
    assert Occurs(s2, x) == Occurs(s1, x) - (if s1[j] == x then 1 else 0) + (if si == x then 1 else 0);
    assert (if s1[j] == x then 1 else 0) == dj;
    assert (if si == x then 1 else 0) == di;
    assert Occurs(s2, x) == Occurs(s, x) - di + dj - dj + di;
    if si == x && sj == x {
      assert di == 1 && dj == 1;
      assert Occurs(s2, x) == Occurs(s, x);
    } else if si == x && sj != x {
      assert di == 1 && dj == 0;
      assert Occurs(s2, x) == Occurs(s, x);
    } else if si != x && sj == x {
      assert di == 0 && dj == 1;
      assert Occurs(s2, x) == Occurs(s, x);
    } else {
      assert di == 0 && dj == 0;
      assert Occurs(s2, x) == Occurs(s, x);
    }
    assert s2 == (s[i := s[j]])[j := s[i]];
    assert Occurs(s2, x) == Occurs(s, x);
  }
}

lemma SwapMs(s: seq<int>, i: int, j: int)
  requires 0 <= i < |s|
  requires 0 <= j < |s|
  ensures multiset((s[i := s[j]])[j := s[i]]) == multiset(s)
{
  var t := (s[i := s[j]])[j := s[i]];
  forall x: int
    ensures multiset(t)[x] == multiset(s)[x]
  {
    OccursSwap(s, i, j, x);
    assert t == (s[i := s[j]])[j := s[i]];
    assert Occurs(t, x) == Occurs(s, x);
    OccursEqMultiset(t, x);
    OccursEqMultiset(s, x);
    assert multiset(t)[x] == Occurs(t, x);
    assert multiset(s)[x] == Occurs(s, x);
    assert multiset(t)[x] == multiset(s)[x];
  }
  MultisetExt(multiset(t), multiset(s));
}

lemma SwapIndex(s: seq<int>, i: int, j: int)
  requires 0 <= i < |s| && 0 <= j < |s|
  ensures Swapped(s, i, j)[i] == s[j]
  ensures Swapped(s, i, j)[j] == s[i]
  ensures forall n {:trigger Swapped(s, i, j)[n]} :: 0 <= n < |s| && n != i && n != j ==> Swapped(s, i, j)[n] == s[n]
{
  var s2 := Swapped(s, i, j);
  assert s2 == (s[i := s[j]])[j := s[i]];
  if i == j {
    DoubleUpdateSame(s, i);
    assert s[j] == s[i];
    assert s2 == (s[i := s[i]])[i := s[i]];
    assert s2 == s;
    assert s2[i] == s[i];
    assert s2[i] == s[j];
    assert s2[j] == s[i];
    assert forall n :: 0 <= n < |s| && n != i && n != j ==> s2[n] == s[n];
  } else {
    var s1 := s[i := s[j]];
    UpdateAt(s, i, s[j]);
    assert s1[i] == s[j];
    UpdateOther(s, i, j, s[j]);
    assert s1[j] == s[j];
    assert s2 == (s1[j := s[i]]);
    UpdateAt(s1, j, s[i]);
    assert s2[j] == s[i];
    UpdateOther(s1, j, i, s[i]);
    assert s2[i] == s1[i];
    assert s2[i] == s[j];
    forall n | 0 <= n < |s| && n != i && n != j
      ensures s2[n] == s[n]
    {
      UpdateOther(s, i, n, s[j]);
      assert s1[n] == s[n];
      UpdateOther(s1, j, n, s[i]);
      assert s2[n] == s1[n];
      assert s2[n] == s[n];
    }
    assert forall n :: 0 <= n < |s| && n != i && n != j ==> s2[n] == s[n];
  }
}

lemma AssignSeq(pre: seq<int>, i: int, v: int, post: seq<int>)
  requires 0 <= i < |pre|
  requires |post| == |pre|
  requires post[i] == v
  requires forall n :: 0 <= n < |pre| && n != i ==> post[n] == pre[n]
  ensures post == pre[i := v]
{
  var u := pre[i := v];
  UpdateAt(pre, i, v);
  assert |u| == |pre|;
  forall n | 0 <= n < |pre|
    ensures post[n] == u[n]
  {
    if n == i {
      assert u[n] == v;
      assert post[n] == v;
    } else {
      UpdateOther(pre, i, n, v);
      assert u[n] == pre[n];
      assert post[n] == pre[n];
    }
  }
  assert forall n :: 0 <= n < |post| ==> post[n] == u[n];
  SeqExt(post, u);
}

lemma PartitionStep(pre: seq<int>, oldk: int, oj: int, pivot: int)
  requires 0 <= oldk <= oj < |pre|
  requires forall n {:trigger pre[n]} :: 0 <= n < oldk ==> pre[n] < pivot
  requires forall n {:trigger pre[n]} :: oldk <= n < oj ==> pre[n] >= pivot
  requires pre[oj] < pivot
  ensures forall n {:trigger Swapped(pre, oldk, oj)[n]} :: 0 <= n < oldk + 1 ==> Swapped(pre, oldk, oj)[n] < pivot
  ensures forall n {:trigger Swapped(pre, oldk, oj)[n]} :: oldk + 1 <= n < oj + 1 ==> Swapped(pre, oldk, oj)[n] >= pivot
  ensures multiset(Swapped(pre, oldk, oj)) == multiset(pre)
{
  var post := Swapped(pre, oldk, oj);
  assert post == (pre[oldk := pre[oj]])[oj := pre[oldk]];
  SwapIndex(pre, oldk, oj);
  SwapMs(pre, oldk, oj);
  assert multiset((pre[oldk := pre[oj]])[oj := pre[oldk]]) == multiset(pre);
  assert multiset(post) == multiset(pre);
  assert Swapped(pre, oldk, oj)[oldk] == pre[oj];
  assert Swapped(pre, oldk, oj)[oj] == pre[oldk];
  assert post[oldk] == pre[oj];
  assert post[oj] == pre[oldk];

  forall n | 0 <= n < |pre| && n != oldk && n != oj
    ensures post[n] == pre[n]
  {
    assert Swapped(pre, oldk, oj)[n] == pre[n];
    assert post[n] == Swapped(pre, oldk, oj)[n];
  }

  forall n | 0 <= n < oldk + 1
    ensures post[n] < pivot
  {
    if n < oldk {
      assert n != oldk;
      assert n != oj;
      assert post[n] == pre[n];
      assert pre[n] < pivot;
    } else {
      assert n == oldk;
      assert post[n] == pre[oj];
      assert pre[oj] < pivot;
    }
  }

  forall n | oldk + 1 <= n < oj + 1
    ensures post[n] >= pivot
  {
    assert oldk + 1 <= n < oj + 1;
    assert oldk < oj;
    if n == oj {
      assert post[oj] == pre[oldk];
      assert oldk <= oldk < oj;
      assert pre[oldk] >= pivot;
    } else {
      assert n != oj;
      assert n != oldk;
      assert oldk < n < oj;
      assert post[n] == pre[n];
      assert pre[n] >= pivot;
    }
  }

  assert forall n :: 0 <= n < oldk + 1 ==> post[n] < pivot;
  assert forall n :: oldk + 1 <= n < oj + 1 ==> post[n] >= pivot;
  forall n | 0 <= n < oldk + 1
    ensures Swapped(pre, oldk, oj)[n] < pivot
  {
    assert post[n] < pivot;
    assert Swapped(pre, oldk, oj)[n] == post[n];
  }
  forall n | oldk + 1 <= n < oj + 1
    ensures Swapped(pre, oldk, oj)[n] >= pivot
  {
    assert post[n] >= pivot;
    assert Swapped(pre, oldk, oj)[n] == post[n];
  }
}

method Partition(a: array<int>, pivot: int) returns (k: int)
  modifies a
  ensures 0 <= k <= a.Length
  ensures forall i :: 0 <= i < k ==> a[i] < pivot
  ensures forall i :: k <= i < a.Length ==> a[i] >= pivot
  ensures multiset(a[..]) == multiset(old(a[..]))
{
  assert a[..] == old(a[..]);
  k := 0;
  var j := 0;
  ghost var original := a[..];
  assert original == old(a[..]);

  while j < a.Length
    invariant 0 <= k <= j <= a.Length
    invariant forall i :: 0 <= i < k ==> a[i] < pivot
    invariant forall i :: k <= i < j ==> a[i] >= pivot
    invariant multiset(a[..]) == multiset(original)
    invariant original == old(a[..])
    decreases a.Length - j
  {
    if a[j] < pivot {
      label PreState:
      ghost var pre := a[..];
      var oldk := k;
      var oj := j;

      forall n | 0 <= n < a.Length
        ensures pre[n] == old@PreState(a[n])
      {
        assert pre[n] == a[n];
        assert old@PreState(a[n]) == a[n];
      }

      forall n | 0 <= n < oldk
        ensures pre[n] < pivot
      {
        assert pre[n] == a[n];
        assert a[n] < pivot;
      }

      forall n | oldk <= n < oj
        ensures pre[n] >= pivot
      {
        assert pre[n] == a[n];
        assert a[n] >= pivot;
      }

      assert a[oj] < pivot;
      assert pre[oj] == a[oj];
      assert pre[oj] < pivot;
      assert |pre| == a.Length;
      assert 0 <= oldk <= oj < |pre|;
      assert multiset(a[..]) == multiset(original);
      assert multiset(pre) == multiset(a[..]);
      assert multiset(pre) == multiset(original);

      PartitionStep(pre, oldk, oj, pivot);

      var vk := a[oldk];
      var vj := a[oj];
      assert vk == pre[oldk];
      assert vj == pre[oj];

      a[oldk] := vj;

      label MidState:
      ghost var mid := a[..];
      assert a[oldk] == vj;
      assert forall n :: 0 <= n < a.Length && n != oldk ==> a[n] == old@PreState(a[n]);

      forall n | 0 <= n < a.Length
        ensures mid[n] == old@MidState(a[n])
      {
        assert mid[n] == a[n];
        assert old@MidState(a[n]) == a[n];
      }

      forall n | 0 <= n < a.Length && n != oldk
        ensures mid[n] == pre[n]
      {
        assert a[n] == old@PreState(a[n]);
        assert pre[n] == old@PreState(a[n]);
        assert mid[n] == a[n];
      }

      assert mid[oldk] == a[oldk];
      assert mid[oldk] == vj;
      assert |mid| == |pre|;
      assert forall n :: 0 <= n < |pre| && n != oldk ==> mid[n] == pre[n];
      AssignSeq(pre, oldk, vj, mid);
      assert mid == pre[oldk := vj];

      a[oj] := vk;
      ghost var post := a[..];
      assert a[..] == post;
      assert a[oj] == vk;
      assert forall n :: 0 <= n < a.Length && n != oj ==> a[n] == old@MidState(a[n]);

      forall n | 0 <= n < a.Length && n != oj
        ensures post[n] == mid[n]
      {
        assert a[n] == old@MidState(a[n]);
        assert mid[n] == old@MidState(a[n]);
        assert post[n] == a[n];
      }

      assert post[oj] == vk;
      assert |post| == |mid|;
      assert forall n :: 0 <= n < |mid| && n != oj ==> post[n] == mid[n];
      AssignSeq(mid, oj, vk, post);
      assert post == mid[oj := vk];
      assert post == (pre[oldk := vj])[oj := vk];
      assert pre[oldk := vj] == pre[oldk := pre[oj]];
      assert post == (pre[oldk := pre[oj]])[oj := vk];
      assert vk == pre[oldk];
      assert post == (pre[oldk := pre[oj]])[oj := pre[oldk]];
      assert post == Swapped(pre, oldk, oj);

      assert multiset(Swapped(pre, oldk, oj)) == multiset(pre);
      assert multiset(post) == multiset(Swapped(pre, oldk, oj));
      assert multiset(post) == multiset(pre);
      assert a[..] == post;
      assert multiset(a[..]) == multiset(post);
      assert multiset(a[..]) == multiset(original);

      k := oldk + 1;
      j := j + 1;
      assert k == oldk + 1;
      assert j == oj + 1;
      assert 0 <= k <= j <= a.Length;
      assert a[..] == post;

      forall n | 0 <= n < k
        ensures a[n] < pivot
      {
        assert a[n] == post[n];
        assert post[n] == Swapped(pre, oldk, oj)[n];
        assert 0 <= n < oldk + 1;
        assert Swapped(pre, oldk, oj)[n] < pivot;
        assert a[n] < pivot;
      }

      forall n | k <= n < j
        ensures a[n] >= pivot
      {
        assert a[n] == post[n];
        assert post[n] == Swapped(pre, oldk, oj)[n];
        assert oldk + 1 <= n < oj + 1;
        assert Swapped(pre, oldk, oj)[n] >= pivot;
        assert a[n] >= pivot;
      }
    } else {
      var oj := j;
      assert a[oj] >= pivot;
      forall n | k <= n < oj
        ensures a[n] >= pivot
      {
        assert a[n] >= pivot;
      }
      j := j + 1;
      assert j == oj + 1;
      assert 0 <= k <= j <= a.Length;
      forall n | k <= n < j
        ensures a[n] >= pivot
      {
        if n < oj {
          assert a[n] >= pivot;
        } else {
          assert n == oj;
          assert a[n] >= pivot;
        }
      }
      assert forall n :: 0 <= n < k ==> a[n] < pivot;
      assert multiset(a[..]) == multiset(original);
    }
  }
  assert j == a.Length;
  assert multiset(a[..]) == multiset(original);
  assert original == old(a[..]);
}
