lemma DecomposeAt(s: seq<int>, i: int)
  requires 0 <= i < |s|
  ensures s == s[..i] + [s[i]] + s[i+1..]
{
  var A := s[..i];
  var mid := [s[i]];
  var C := s[i+1..];
  var Am := A + mid;
  var r := Am + C;
  assert |A| == i;
  assert |mid| == 1;
  assert |Am| == i + 1;
  assert |C| == |s| - (i + 1);
  assert |r| == |s|;
  forall p | 0 <= p < |s|
    ensures r[p] == s[p]
  {
    if p < i {
      assert p < |A|;
      assert Am[p] == A[p];
      assert r[p] == Am[p];
      assert A[p] == s[p];
    } else if p == i {
      assert Am[p] == mid[0];
      assert mid[0] == s[i];
      assert r[p] == Am[p];
    } else {
      var kk := p - (i + 1);
      assert 0 <= kk < |C|;
      assert r[p] == C[kk];
      assert C[kk] == s[(i + 1) + kk];
      assert (i + 1) + kk == p;
    }
  }
  SeqExt(r, s);
}

