  var mid := [v];
  var C := s[i+1..];
  var Am := A + mid;
  var r := Am + C;
  var t := s[i := v];
  assert |A| == i;
  assert |Am| == i + 1;
  assert |r| == |s|;
  forall p | 0 <= p < |s|
    ensures t[p] == r[p]
  {
    if p < i {
      assert t[p] == s[p];
      assert p < |A|;
      assert Am[p] == A[p];
      assert r[p] == Am[p];
      assert A[p] == s[p];
    } else if p == i {
      assert t[p] == v;
      assert Am[p] == mid[0];
      assert r[p] == Am[p];
    } else {
      var kk := p - (i + 1);
      assert t[p] == s[p];
      assert 0 <= kk < |C|;
      assert r[p] == C[kk];
      assert C[kk] == s[(i + 1) + kk];
      assert (i + 1) + kk == p;
    }
  }
  SeqExt(t, r);
}

lemma UpdateMultiset(s: seq<int>, i: int, v: int)
  requires 0 <= i < |s|
  ensures multiset(s[i := v]) == (multiset(s) - multiset{s[i]}) + multiset{v}
{
  DecomposeAt(s, i);
  UpdateEq(s, i, v);
  var A := s[..i];
  var C := s[i+1..];
  var oldv := s[i];
  assert s == (A + [oldv]) + C;
  assert s[i := v] == (A + [v]) + C;
  assert multiset(s) == multiset(A + [oldv]) + multiset(C);
  assert multiset(A + [oldv]) == multiset(A) + multiset([oldv]);
  assert multiset([oldv]) == multiset{oldv};
  assert multiset(s[i := v]) == multiset(A + [v]) + multiset(C);
  assert multiset(A + [v]) == multiset(A) + multiset([v]);
  assert multiset([v]) == multiset{v};

  var mA := multiset(A);
  var mC := multiset(C);
  var m := multiset(s);
  var mp := multiset(s[i := v]);
  var target := (m - multiset{oldv}) + multiset{v};

  forall x
    ensures mp[x] == target[x]
  {
    assert m[x] == (mA + multiset{oldv})[x] + mC[x];
    assert (mA + multiset{oldv})[x] == mA[x] + multiset{oldv}[x];
    assert m[x] == mA[x] + multiset{oldv}[x] + mC[x];
    assert mp[x] == mA[x] + multiset{v}[x] + mC[x];
    assert m[x] >= multiset{oldv}[x];
    assert (m - multiset{oldv})[x] == m[x] - multiset{oldv}[x];
    assert target[x] == (m - multiset{oldv})[x] + multiset{v}[x];
    assert m[x] - multiset{oldv}[x] == mA[x] + mC[x];
    assert target[x] == mA[x] + mC[x] + multiset{v}[x];
  }
  MultisetExt(mp, target);
}

