method Swap(a: array<int>, i: int, j: int)
  requires 0 <= i < j < a.Length
  modifies a
  ensures multiset(a[..]) == multiset(old(a[..]))
  ensures forall p :: 0 <= p < a.Length ==>
      a[p] == (if p == i then old(a[j]) else if p == j then old(a[i]) else old(a[p]))
{
  ghost var prev := a[..];
  assert prev == old(a[..]);
  forall p | 0 <= p < a.Length
    ensures prev[p] == old(a[p])
  {
    assert prev[p] == a[p];
    assert a[p] == old(a[p]);
  }

  var vLeft := a[i];
  var vRight := a[j];
  assert vLeft == prev[i];
  assert prev[i] == old(a[i]);
  assert vRight == prev[j];
  assert prev[j] == old(a[j]);

  a[i] := vRight;

  ghost var mid := a[..];
  forall p | 0 <= p < a.Length
    ensures mid[p] == (if p == i then vRight else prev[p])
  {
    if p == i {
      assert a[p] == vRight;
      assert mid[p] == a[p];
    } else {
      assert a[p] == old(a[p]);
      assert old(a[p]) == prev[p];
      assert a[p] == prev[p];
      assert mid[p] == a[p];
    }
  }

  a[j] := vLeft;

  forall p | 0 <= p < a.Length
    ensures a[p] == (if p == j then vLeft else mid[p])
  {
    if p == j {
      assert a[p] == vLeft;
    } else {
      assert a[p] == mid[p];
    }
  }

  forall p | 0 <= p < a.Length
    ensures a[p] == (if p == i then old(a[j]) else if p == j then old(a[i]) else old(a[p]))
  {
    if p == j {
      assert a[p] == vLeft;
      assert vLeft == old(a[i]);
    } else if p == i {
      assert p != j;
      assert a[p] == mid[p];
      assert mid[p] == vRight;
      assert vRight == old(a[j]);
    } else {
      assert a[p] == mid[p];
      assert mid[p] == prev[p];
      assert prev[p] == old(a[p]);
    }
  }

  ghost var swapped := (prev[i := prev[j]])[j := prev[i]];
  forall p | 0 <= p < a.Length
    ensures a[..][p] == swapped[p]
  {
    SwappedElem(prev, i, j, p);
    assert swapped[p] == (if p == i then prev[j] else if p == j then prev[i] else prev[p]);
    assert a[p] == (if p == i then old(a[j]) else if p == j then old(a[i]) else old(a[p]));
    assert prev[i] == old(a[i]);
    assert prev[j] == old(a[j]);
    assert prev[p] == old(a[p]);
    assert a[p] == swapped[p];
    assert a[..][p] == a[p];
  }
  assert |prev| == a.Length;
  assert |swapped| == |prev|;
  assert |a[..]| == a.Length;
  SeqExt(a[..], swapped);
  SwapMultiset(prev, i, j);
  assert multiset(swapped) == multiset(prev);
  assert multiset(a[..]) == multiset(swapped);
  assert multiset(prev) == multiset(old(a[..]));
  assert multiset(a[..]) == multiset(old(a[..]));
}

method Partition(a: array<int>, pivot: int) returns (k: int)
