  var j := 0;
  while j < a.Length
    invariant 0 <= k <= j <= a.Length
    invariant forall p :: 0 <= p < k ==> a[p] < pivot
    invariant forall p :: k <= p < j ==> a[p] >= pivot
    invariant multiset(a[..]) == multiset(old(a[..]))
    decreases a.Length - j
