    var jNext := j + 1;
    assert jNext == j + 1;
    assert jNext <= a.Length;

    if a[j] < pivot {
      if k < j {
        ghost var snap := a[..];
        ghost var mOld := multiset(a[..]);
        assert mOld == multiset(old(a[..]));
        assert multiset(snap) == mOld;

        forall p | 0 <= p < a.Length
          ensures snap[p] == a[p]
        {
        }

        forall p | 0 <= p < k
          ensures snap[p] < pivot
        {
          assert snap[p] == a[p];
        }
        forall p | k <= p < j
          ensures snap[p] >= pivot
        {
          assert snap[p] == a[p];
        }
        assert snap[j] == a[j];
        assert snap[j] < pivot;
        assert snap[k] >= pivot;

