          } else {
            assert p == j;
            assert a[p] >= pivot;
          }
        }

        k := kk + 1;
        assert k == kk + 1;
        assert 0 <= k <= jNext <= a.Length;
        assert forall p :: 0 <= p < k ==> a[p] < pivot;
        assert forall p :: k <= p < jNext ==> a[p] >= pivot;
        assert multiset(a[..]) == mOld;
