        assert newK == jNext;
        forall p | 0 <= p < newK
          ensures a[p] < pivot
        {
          if p < k {
            assert a[p] < pivot;
          } else {
            assert p == k;
            assert p == j;
            assert a[p] < pivot;
          }
        }
        k := newK;
        assert k == jNext;
        forall p | k <= p < jNext
          ensures a[p] >= pivot
        {
          assert k == jNext;
          assert k <= p && p < jNext;
          assert false;
        }
        assert 0 <= k <= jNext <= a.Length;
        assert forall p :: 0 <= p < k ==> a[p] < pivot;
        assert multiset(a[..]) == multiset(old(a[..]));
      }
    } else {
      assert a[j] >= pivot;
      forall p | k <= p < jNext
        ensures a[p] >= pivot
      {
        if p < j {
          assert k <= p < j;
          assert a[p] >= pivot;
        } else {
          assert p == j;
          assert a[p] >= pivot;
