lemma Div2Order(n: int, i: int)
  requires n >= 0
  requires 0 <= i < n / 2
  ensures i < n - 1 - i
  ensures 0 <= n - 1 - i
  ensures n - 1 - i < n
{
  var q := n / 2;
  var r := n % 2;
  assert n == 2 * (n / 2) + (n % 2);
  assert n == 2 * q + r;
  assert 0 <= r < 2;
  assert i <= q - 1;
  assert i + i <= (q - 1) + (q - 1);
  assert (q - 1) + (q - 1) == q + q - 2;
  assert q + q == 2 * q;
  assert 2 * q == n - r;
  assert q + q - 2 == n - r - 2;
  assert n - r - 2 <= n - 2;
  assert i + i <= n - 2;
  assert i + i < n - 1;
  assert i < n - 1 - i;
  assert 0 <= n - 1 - i;
  assert n - 1 - i < n;
}

lemma MiddleIndex(n: int, k: int)
  requires n >= 0
  requires n / 2 <= k < n - n / 2
  ensures k == n - 1 - k
{
  var q := n / 2;
  var r := n % 2;
  assert n == 2 * (n / 2) + (n % 2);
  assert n == 2 * q + r;
  assert 0 <= r < 2;
  assert q + q == 2 * q;
  assert n == q + q + r;
  assert n - q == q + r;
  assert q <= k;
  assert k < n - q;
  assert k < q + r;
  if r == 0 {
    assert false;
  } else {
    assert r == 1;
    assert k == q;
    assert n - 1 - k == 2 * q + r - 1 - k;
    assert 2 * q + r - 1 - k == 2 * q + 1 - 1 - q;
    assert 2 * q + 1 - 1 - q == q;
    assert n - 1 - k == k;
  }
}

