lemma ReverseDone(a: array<int>, original: seq<int>, i: int)
  requires a.Length == |original|
  requires 0 <= i == a.Length / 2
  requires forall k :: 0 <= k < i ==> 0 <= a.Length - 1 - k < a.Length
  requires forall k :: 0 <= k < i ==> a[k] == original[a.Length - 1 - k]
  requires forall k :: 0 <= k < i ==> a[a.Length - 1 - k] == original[k]
  requires forall k :: i <= k < a.Length - i ==> a[k] == original[k]
  ensures forall k :: 0 <= k < a.Length ==> a[k] == original[a.Length - 1 - k]
{
  var n := a.Length;
  forall k | 0 <= k < n
    ensures a[k] == original[n - 1 - k]
  {
    if k < i {
      assert a[k] == original[n - 1 - k];
    } else if k >= n - i {
      assert n - i <= k <= n - 1;
      assert n - i <= n - 1;
      assert i >= 1;
      var j := n - 1 - k;
      assert j >= 0;
      assert j <= n - 1 - (n - i);
      assert n - 1 - (n - i) == i - 1;
      assert 0 <= j < i;
      assert 0 <= n - 1 - j < n;
      assert a[n - 1 - j] == original[j];
      assert n - 1 - j == k;
      assert j == n - 1 - k;
      assert a[k] == original[n - 1 - k];
    } else {
      assert i <= k < n - i;
      assert a[k] == original[k];
      assert i < n - i;
      assert 2 * i < n;
      assert n == 2 * (n / 2) + n % 2;
      assert 2 * (n / 2) < n;
      assert n % 2 == 0 || n % 2 == 1;
      assert n % 2 == 1;
      assert n == 2 * i + 1;
      assert n - i == i + 1;
      assert k == i;
      assert n - 1 - i == 2 * i + 1 - 1 - i;
      assert 2 * i + 1 - 1 - i == i;
      assert n - 1 - k == k;
      assert a[k] == original[n - 1 - k];
    }
  }
